function toast(text){
  clearTimeout(toastTimer);
  if(isOverlay){const label=document.querySelector('[data-island-status]');if(label){const original=label.textContent;label.textContent=text;label.title=text;label.classList.add('has-message');toastTimer=setTimeout(()=>{if(label.isConnected){label.textContent=original;label.classList.remove('has-message');label.removeAttribute('title');}},3800);}return;}
  const t=document.querySelector('#toast');setText(t,text);t.classList.add('visible');toastTimer=setTimeout(()=>t.classList.remove('visible'),3800);
}
function setText(el,value){const text=String(value??'');if(el&&el.textContent!==text)el.textContent=text;}
function setAttribute(el,key,value){const text=String(value);if(el.getAttribute(key)!==text)el.setAttribute(key,text);}
function setClass(el,key,value){if(el.classList.contains(key)!==!!value)el.classList.toggle(key,!!value);}
// Original renderer-frame counter from the user-supplied build. Not game telemetry.
function uiVisible(){return nativeVisible&&(!isOverlay||state.settings.enabled);}
function playerVisible(){return uiVisible()&&(!isOverlay&&page==='music'||expanded&&tab==='music');}
function syncUITimers(){
  clearTimeout(clockTimer);clearTimeout(progressTimer);clockTimer=progressTimer=undefined;
  const visible=uiVisible();document.documentElement.classList.toggle('ui-paused',!visible);
  
  if(!visible)return;
  if(document.querySelector('.big-clock,.island-compact [data-clock],.island.expanded [data-clock]')){
    const tick=()=>{updateClocks();const delay=state.settings.showSeconds?1000-(Date.now()%1000):60000-(Date.now()%60000);clockTimer=setTimeout(tick,delay+8);};tick();
  }
  if(state.media.playing&&playerVisible()){
    const tick=()=>{updateProgress();progressTimer=setTimeout(tick,250);};tick();
  }
}
function receiveSettings(value){
  const previous=state.settings;state.settings=syncIslandAccent({...DEFAULTS,...value});applySettings();
  if(previous.showMusic!==state.settings.showMusic||previous.showWeather!==state.settings.showWeather||previous.showDownloads!==state.settings.showDownloads)renderIsland();
  else{const mount=document.querySelector('.island-mount');if(mount)mount.style.opacity=isOverlay?'1':state.settings.enabled?'1':'.4';updateClocks();if(previous.scale!==state.settings.scale||previous.radius!==state.settings.radius)reportBoundsDuringTransition();}
}

