function performanceRow(){return `<div class="setting-row"><span class="setting-icon">${icon('power')}</span><span class="setting-copy"><strong>Нагрузка на ПК</strong><small>Экономный режим убирает постоянные анимации, blur и свечение островка</small></span>${choice('performanceMode','Нагрузка на ПК',[['balanced','Баланс'],['eco','Экономный'],['quality','Все эффекты']],state.settings.performanceMode)}</div>`;}
function overview(){return `${preview()}<div class="widgets">${clockWidget()}${weatherWidget()}${musicWidget()}</div>${sectionTitle('ПОД ВАШ РИТМ','Ближе к вам',`<button class="text-button" data-nav="appearance">Все настройки ${icon('arrow')}</button>`)}<section class="settings-card">${startupRow()}${performanceRow()}${toggleRow('enabled','Показывать остров','Ваш маленький помощник в верхней части экрана','layers')}${toggleRow('topmost','Поверх других окон','Оставайтесь в курсе, чем бы вы ни занимались','monitor')}${toggleRow('sounds','Звуки интерфейса','Тихие, приятные отклики на ваши действия','volume')}</section><div class="subtle-note">${icon('spark')} Хорошие вещи не должны занимать много места.</div>`;}
const rendererNames=[['modern','Современный'],['liquid','Жидкое стекло'],['frosted','Матовый blur']];
function rendererSelect(key,title,description){return `<div class="setting-row"><span class="setting-icon">${icon('layers')}</span><span class="setting-copy"><strong>${title}</strong><small>${description}</small></span>${choice(key,title,rendererNames,state.settings[key])}</div>`;}
function colorRow(key,title,description){return `<div class="setting-row"><span class="setting-icon">${icon('spark')}</span><span class="setting-copy"><strong>${title}</strong><small>${description}</small></span>${colorControl(key,title,state.settings[key])}</div>`;}
function palettePreview(){return `<div class="palette-preview"><div><span class="eyebrow">ВАША ПАЛИТРА</span><strong>EclipseIsland</strong><span>Цвета, которые приятно видеть каждый день.</span></div><span class="palette-a">Aa</span><div class="palette-samples"><i></i><i></i><i></i></div><span class="contrast-tag" data-contrast></span></div>`;}
function updatePalettePreview(settings){
  const el=document.querySelector('.palette-preview');if(!el)return;
  const accent=settings.accent==='custom'?settings.customAccent:PALETTES[settings.accent]||PALETTES.violet;
  el.style.setProperty('--sample-accent',safeColor(accent));el.style.setProperty('--sample-surface',safeColor(settings.surfaceColor));el.style.setProperty('--sample-text',safeColor(settings.textColor));
  const base=contrastRatio(settings.textColor,settings.surfaceColor);
  const island=settings.advancedTheme?Math.min(contrastRatio(settings.islandText,settings.islandSurface),settings.gradientEnabled?contrastRatio(settings.islandText,settings.islandGradient):Infinity):base;
  const warning=Math.min(base,island)<4.5;
  el.querySelector('[data-contrast]').textContent=`Текст ${base.toFixed(1)}:1 · остров ${island.toFixed(1)}:1${warning?' · низкий контраст':''}`;
  el.querySelector('[data-contrast]').classList.toggle('low-contrast',warning);
}
function sourceOptions(){const items=[['auto','Автоматически']];for(const session of state.media.sessions||[])if(session.id&&!items.some(item=>item[0]===session.id))items.push([session.id,sourceLabel(session.id)+(session.playing?' · играет':'')]);if(state.settings.mediaSource!=='auto'&&!items.some(item=>item[0]===state.settings.mediaSource))items.push([state.settings.mediaSource,sourceLabel(state.settings.mediaSource)+' · недоступен']);return items;}
function mediaSourceRow(){return `<div class="setting-row"><span class="setting-icon">${icon('headphones')}</span><span class="setting-copy"><strong>Плеер</strong><small>Выберите источник, если открыто несколько приложений</small></span><span data-source-picker>${choice('mediaSource','Плеер',sourceOptions(),state.settings.mediaSource)}</span></div>`;}
function updateSourceOptions(){const host=document.querySelector('[data-source-picker]');if(host){host.innerHTML=choice('mediaSource','Плеер',sourceOptions(),state.settings.mediaSource);syncControls(host);}}

function themeStudio(){return `
  ${sectionTitle('КОЛЛЕКЦИЯ','Готовые цветовые темы')}
  <div class="theme-presets">${colorThemes.map(([id,name,p])=>`<button type="button" class="theme-preset" data-color-theme="${id}" aria-pressed="false" style="--preset-bg:${p.surfaceColor};--preset-card:${p.cardColor};--preset-accent:${p.customAccent};--preset-text:${p.textColor}"><span class="theme-mini"><i></i><b></b><em></em></span><strong>${name}</strong><span class="theme-preset-check">${icon('check')}</span></button>`).join('')}</div>
  ${sectionTitle('СТУДИЯ ОФОРМЛЕНИЯ','Точная настройка')}
  <section class="settings-card">${toggleRow('advancedTheme','Расширенная палитра','Отдельные цвета фона и текста, дополнительные эффекты','sliders')}</section>
  <div class="advanced-theme-panel">
  <div class="studio-live-sample"><span><strong>Палитра островка</strong><small>Обновляется при выборе цвета</small></span><div class="studio-sample-island"><span>${icon('spark')} 12:45</span><span>${icon('music')} <i>Музыка</i></span></div></div>
  ${sectionTitle('ИНТЕРФЕЙС','Окно настроек')}
  <section class="settings-card">
  ${colorRow('sidebarColor','Боковое меню','Фон навигации')}${colorRow('cardColor','Карточки','Фон настроек, виджетов и полей')}${colorRow('mutedColor','Второстепенный текст','Подписи и пояснения')}${colorRow('lineColor','Разделители','Границы карточек и линий')}${colorRow('buttonColor','Основные кнопки','Заливка кнопок действий')}${colorRow('buttonText','Текст кнопок','Надписи и иконки на заливке')}${rangeRow('cardRadius','Скругление карточек','Форма панелей настроек',4,24,'layers')}</section>
  ${sectionTitle('ОСТРОВОК','Своя палитра')}
  <section class="settings-card">${colorRow('islandSurface','Основной фон','Цвет компактного и раскрытого островка')}${colorRow('islandGradient','Второй цвет','Конечный оттенок градиента')}${toggleRow('gradientEnabled','Градиент','Плавный переход между двумя цветами','layers')}${rangeRow('gradientAngle','Направление градиента','Угол перехода цветов',0,360,'sliders')}${colorRow('islandText','Основной текст','Часы, названия и содержимое')}${colorRow('islandMuted','Второстепенный текст','Подписи, даты и неактивные вкладки')}${toggleRow('separateIslandAccent','Отдельный акцент островка','По умолчанию используется общий выбранный акцент','spark')}${colorRow('islandAccent','Акцент островка','Ручной выбор включает отдельный акцент')}${rangeRow('islandOpacity','Непрозрачность островка','15% — почти прозрачный, 100% — плотный фон',15,100,'layers')}${rangeRow('compactRadius','Скругление компактного островка','От прямоугольника до капсулы',10,30,'layers')}</section>
  ${sectionTitle('КРОМКА И СВЕТ','Рамка, тень и свечение')}
  <section class="settings-card">${colorRow('islandBorder','Цвет рамки','Одинаковая кромка на всех вкладках')}${rangeRow('borderWidth','Толщина рамки','0 — без рамки',0,3,'layers')}${rangeRow('borderOpacity','Видимость рамки','От невидимой до плотной',0,100,'layers')}${colorRow('glowColor','Цвет свечения','Независимо от акцента')}${colorRow('shadowColor','Цвет тени','Цвет мягкой тени и внутренней кромки')}${rangeRow('shadowStrength','Интенсивность тени','0 — без тени',0,75,'sun')}${rangeRow('shadowBlur','Мягкость тени','Радиус рассеивания',0,36,'cloud')}</section>
  <div class="material-note">${icon('info')} Цвета и эффекты применяются к предпросмотру сразу. Настройки сохраняются при отпускании ползунка или применении цвета. Низкая непрозрачность зависит от фона рабочего стола. В Windows внешние тени могут обрезаться нативной формой окна, поэтому добавлена внутренняя подсветка.</div>
  </div>`;}
function appearance(){return `${preview()}
  ${sectionTitle('МАТЕРИАЛЫ','Поймайте свой свет')}
  <div class="renderer-cards">${rendererNames.map(([id,name])=>`<button class="renderer-card" data-renderer-preset="${id}" aria-label="Стиль для всего: ${name}"><span class="material-sample" data-material="${id}"><i></i><i></i><i></i></span><strong>${name}</strong><span>${id==='modern'?'Чётко. Спокойно. Знакомо.':id==='liquid'?'Прозрачность, блики и глубина.':'Мягкое рассеянное стекло.'}</span><span class="renderer-check">${icon('check')}</span></button>`).join('')}</div>
  <section class="settings-card material-settings"><div class="setting-row"><span class="setting-icon">${icon('spark')}</span><span class="setting-copy"><strong>Единый стиль</strong><small>Применить сразу ко всему приложению</small></span>${choice('all','Единый стиль',rendererNames,'mixed',{all:true})}</div>
  ${rendererSelect('uiRenderer','Окно настроек','Материал панелей и карточек')}
  ${rendererSelect('islandRenderer','Остров','Ваш парящий центр внимания')}
  ${rendererSelect('loaderRenderer','Загрузочный экран','Первое впечатление при запуске')}</section>
  <div class="material-note">${icon('info')} Жидкое стекло — прозрачный материал с кромкой и бликами, без blur. Матовый стиль размывает слои интерфейса. Рабочий стол под островом не захватывается и не искажается.</div>
  <div class="loader-preview" data-renderer="${state.settings.loaderRenderer}"><div class="loader-tile"><div class="loader-logo" aria-hidden="true">${icon('spark')}</div><strong>EclipseIsland</strong><span class="loader-caption">Всё готово к вашему дню.</span><div class="loader-line"><i></i></div></div><span class="loader-preview-label">ПРЕДПРОСМОТР ЗАГРУЗКИ</span></div>
  ${sectionTitle('ВАША ПАЛИТРА','Цвет без ограничений',`<button class="text-button" data-reset-theme>Вернуть тему ${icon('refresh')}</button>`)}${palettePreview()}
  <section class="settings-card"><div class="setting-row"><span class="setting-icon">${icon('spark')}</span><span class="setting-copy"><strong>Готовые акценты</strong><small>Общий цвет окна и островка; выбор отключает отдельный акцент</small></span><div class="swatches">${[['violet','Лаванда'],['mint','Мята'],['blue','Небо'],['peach','Персик'],['rose','Роза'],['amber','Янтарь']].map(([c,label])=>`<button data-accent="${c}" class="swatch" aria-label="${label}" title="${label}">${icon('check')}</button>`).join('')}</div></div>
  ${colorRow('customAccent','Свой акцент','При выборе включается собственный цвет')}
  ${colorRow('surfaceColor','Цвет поверхности','Основа острова, панелей и стекла')}
  ${colorRow('textColor','Цвет текста','Основной текст и элементы острова')}
  ${rangeRow('opacity','Плотность стекла','Плотность материалов; в расширенной палитре у острова отдельная непрозрачность',35,100,'layers')}
  ${rangeRow('blur','Размытие слоёв','Мягкость стекла внутри интерфейса',0,48,'cloud')}
  ${rangeRow('tint','Цветовой оттенок','Сколько акцента добавить в стекло',0,60,'spark')}
  ${rangeRow('glow','Свечение','Тонкий свет вокруг острова',0,50,'sun')}</section>
  ${themeStudio()}
  ${sectionTitle('ФОРМА','Найдите удобный размер')}
  <section class="settings-card">${rangeRow('scale','Размер острова','От компактного до заметного',80,120,'layers')}${rangeRow('radius','Скругление','Форма раскрытого острова',20,36,'layers')}${rangeRow('offset','Отступ от верхнего края','Найдите комфортное положение',0,120,'monitor')}<div class="setting-row"><span class="setting-icon">${icon('monitor')}</span><span class="setting-copy"><strong>Экран</strong><small>Где будет жить ваш остров</small></span>${choice('monitor','Экран',[['primary','Основной экран'],...state.monitors.map(d=>[d.id,d.label])],state.settings.monitor)}</div></section>
  ${sectionTitle('ПОВЕДЕНИЕ','Детали имеют значение')}<section class="settings-card">${toggleRow('hoverExpand','Раскрывать при наведении','Остров плавно открывается вслед за курсором','spark')}${toggleRow('showSeconds','Показывать секунды','Чуть больше точности в вашем дне','clock')}${toggleRow('hour12','12-часовой формат','Время в формате AM / PM','clock')}${toggleRow('reducedMotion','Уменьшить движение','Спокойные переходы без пружинных анимаций','layers')}${toggleRow('sounds','Звуки интерфейса','Нежные отклики на переключения и действия','volume')}${rangeRow('soundVolume','Громкость откликов','От едва слышных до заметных',0,100,'volume')}</section>
  `;}

function musicControls(large=false){const m=state.media;const active=m.active;return `<div class="player ${large?'large-player':''}"><div class="player-heading"><div data-artwork class="album-art ${m.playing?'playing':''}"><div class="vinyl"></div>${icon('music')}</div><div class="track-copy"><strong data-track-title>${esc(active?m.title||'Без названия':'Пока тихо')}</strong><span data-track-artist>${esc(active?m.artist||'Неизвестный исполнитель':'Включите музыку в любимом плеере')}</span><span class="player-source" data-player-label>${active?esc(sourceLabel(m.source)):'Windows Media Session'}</span></div><span class="equalizer" data-equalizer><i></i><i></i><i></i><i></i></span></div><div class="track-progress"><input type="range" class="seek" min="0" max="${m.duration||1}" step="1" value="${m.position||0}" data-seek aria-label="Позиция воспроизведения" ${!m.canSeek?'disabled':''}><div><span data-position>${trackTime(m.position)}</span><span data-duration>${trackTime(m.duration)}</span></div></div><div class="transport"><button class="icon-button" data-media="previous" aria-label="Предыдущий трек" ${!m.canPrevious?'disabled':''}>${icon('previous')}</button><button class="play-button" data-media="toggle" aria-label="${m.playing?'Пауза':'Воспроизвести'}" ${!m.canToggle?'disabled':''}>${icon(m.playing?'pause':'play')}</button><button class="icon-button" data-media="next" aria-label="Следующий трек" ${!m.canNext?'disabled':''}>${icon('next')}</button></div></div>`;}
function captureConfig(){return {quality:'auto',replayQuality:'auto',height:1080,fps:60,bitrate:16,codec:'auto',noiseSuppression:true,echoCancellation:true,autoGainControl:false,systemAudio:true,microphone:false,systemVolume:100,micVolume:100,audioBitrate:192,countdown:3,maxMinutes:0,maxSizeMB:0,excludeIsland:true,hideSettings:true,showRecording:true,hotkey:'Alt+F9',panelHotkey:'Alt+Z',source:'',folder:'',replayEnabled:false,replaySeconds:30,replayHeight:720,replayFPS:30,replayBitrate:6,replayMaxMB:256,replayHotkey:'Alt+F10',replayMicrophone:false,replayNoiseSuppression:true,replayEchoCancellation:true,replayAutoGainControl:false,replayMicHighPass:false,replayMicCompressor:false,replaySystemAudio:true,replaySystemVolume:100,replayMicVolume:100,replayAudioBitrate:192,...(state.capture?.settings||{})};}
function recordingLabel(){return ({idle:'Готово к записи',starting:'Подключаем экран…',countdown:'Начало через '+(state.capture?.remaining||0),recording:'Идёт запись',paused:'Запись на паузе',stopping:'Сохраняем видео…',exporting:'Готовим MP4…',error:'Запись остановлена'})[state.capture?.status||'idle']||'Готово к записи';}
function recordingBusy(){return !!state.capture?.active||['starting','countdown','stopping','exporting'].includes(state.capture?.status);}
function sizeText(bytes=0){return bytes>1073741824?(bytes/1073741824).toFixed(2)+' ГБ':(bytes/1048576).toFixed(1)+' МБ';}
function captureSelect(key,title,description,options){return `<div class="setting-row"><span class="setting-icon">${icon('sliders')}</span><span class="setting-copy"><strong>${title}</strong><small>${description}</small></span>${choice(key,title,options,captureConfig()[key],{scope:'capture',disabled:recordingBusy()})}</div>`;}

function captureToggle(key,title,description){return `<label class="setting-row"><span class="setting-icon">${icon('check')}</span><span class="setting-copy"><strong>${title}</strong><small>${description}</small></span><input class="toggle" type="checkbox" data-capture-setting="${key}" ${captureConfig()[key]?'checked':''} ${recordingBusy()?'disabled':''}></label>`;}
function captureRange(key,title,min,max,unit){return `<label class="setting-row"><span class="setting-icon">${icon('sliders')}</span><span class="setting-copy"><strong>${title}</strong><small data-capture-value="${key}">${captureConfig()[key]} ${unit}</small></span><input class="capture-range" type="range" min="${min}" max="${max}" value="${captureConfig()[key]}" data-capture-setting="${key}" ${recordingBusy()?'disabled':''}></label>`;}
function captureButtons(){return `<div class="capture-actions"><button class="button capture-start" data-capture-action="start" ${recordingBusy()?'disabled':''}>${icon('record')} Начать запись</button><button class="text-button" data-capture-action="pause" ${!['recording','paused'].includes(state.capture?.status)?'disabled':''}>${icon(state.capture?.status==='paused'?'play':'pause')} ${state.capture?.status==='paused'?'Продолжить':'Пауза'}</button><button class="button capture-stop" data-capture-action="stop" ${!state.capture?.active||['stopping','exporting'].includes(state.capture?.status)?'disabled':''}>${icon('stop')} Остановить</button></div>`;}
function recordingsList(limit=24){const items=(state.capture?.recent||[]).slice(0,limit);return items.length?items.map(item=>`<div class="recording-item"><button class="recording-play" data-capture-action="preview" data-recording-id="${esc(item.id)}" aria-label="Просмотр ${esc(item.name)}">${icon('play')}</button><div class="recording-copy"><strong>${esc(item.name)}</strong><small>${new Date(item.createdAt).toLocaleString('ru-RU')} · ${trackTime(item.duration)} · ${sizeText(item.bytes)}${item.interrupted?' · Неполная запись':''}</small></div><button class="icon-button" data-capture-action="open" data-recording-id="${esc(item.id)}" aria-label="Открыть в плеере">${icon('arrowUp')}</button><button class="icon-button" data-capture-action="reveal" data-recording-id="${esc(item.id)}" aria-label="Показать в папке">${icon('folder')}</button></div>`).join(''):'<div class="recordings-empty">Здесь появятся ваши записи.<br><small>Нажмите «Начать запись» или используйте горячую клавишу.</small></div>';}
function capturePresets(){return `<div class="capture-presets">${[['eco','Экономный','720p · 30 FPS'],['balanced','Баланс','1080p · 60 FPS'],['quality','Чёткий','1440p · 60 FPS']].map(([id,name,detail])=>`<button data-capture-profile="${id}" ${recordingBusy()?'disabled':''} aria-pressed="${captureConfig().height===({eco:720,balanced:1080,quality:1440}[id])&&captureConfig().fps===({eco:30,balanced:60,quality:60}[id])}"><strong>${name}</strong><small>${detail}</small></button>`).join('')}</div>`;}
function capturePage(){const c=captureConfig();return `<div class="feature-banner capture-banner"><div class="feature-icon">${icon('record')}</div><div><span class="eyebrow">СОХРАНИТЕ ВАЖНЫЙ МОМЕНТ</span><h2>Ваш экран. В движении.</h2><p>Запись экрана или окна, звук и быстрый доступ к видео.</p></div><span class="capture-hotkey">${esc(c.panelHotkey)}</span></div><section class="settings-card capture-console"><div class="recording-status"><span class="record-dot ${recordingBusy()?'active':''}"></span><strong data-record-status>${recordingLabel()}</strong><span data-record-size>${sizeText(state.capture?.bytes)}</span></div><div class="recording-timer" data-record-elapsed>${trackTime(state.capture?.elapsed)}</div><div class="capture-meta" data-record-format>${c.height}p · ${c.fps} FPS · ${c.bitrate} Мбит/с</div><div data-capture-buttons>${captureButtons()}</div><p class="capture-error" data-record-error></p><p class="capture-shortcut-note" data-record-shortcuts></p></section>${sectionTitle('ЧТО ЗАПИСЫВАЕМ','Экран или окно')}<section class="settings-card"><label class="setting-row"><span class="setting-icon">${icon('monitor')}</span><span class="setting-copy"><strong>Источник записи</strong><small>Можно выбрать монитор или отдельное окно</small></span><div class="capture-source-choice" data-capture-source-control>${captureSourceChoice()}</div><button class="icon-button" data-capture-refresh aria-label="Обновить источники">${icon('refresh')}</button></label><div class="capture-source-grid" data-capture-sources>${captureSourcesMarkup()}</div></section>${sectionTitle('ДЕТАЛИ И ПЛАВНОСТЬ','Качество записи')}<section class="settings-card">${capturePresets()}${captureSelect('quality','Качество видео','Авто подбирает битрейт по разрешению и FPS',[['auto','Автоматически'],['manual','Вручную']])}${captureSelect('height','Разрешение','Высота кадра, пропорции источника сохраняются',[[360,'360p'],[480,'480p'],[720,'720p HD'],[1080,'1080p Full HD'],[1440,'1440p 2K'],[2160,'2160p 4K']])}${captureSelect('fps','Частота кадров','Целевая частота записи',[[30,'30 FPS'],[60,'60 FPS'],[90,'90 FPS'],[120,'120 FPS'],[144,'144 FPS'],[165,'165 FPS'],[240,'240 FPS']])}${captureRange('bitrate','Ручной битрейт видео',2,200,'Мбит/с')}${captureSelect('codec','Кодек захвата','Итоговое видео — MP4 (H.264 / AAC); H.264 сохраняется без повторного кодирования',[['auto','Авто · быстрый H.264'],['h264','H.264 · быстрое сохранение'],['vp9','VP9 · компактнее'],['vp8','VP8 · легче для ПК']])}</section><div class="info-box">${icon('info')}<p>До 4K и 240 FPS — целевые параметры, а не гарантия частоты. Доступная частота зависит от экрана, видеокарты и нагрузки. Изображение меньшего размера не растягивается искусственно. Фактический размер показывается во время записи.</p></div>${sectionTitle('ВАШ САУНДТРЕК','Звук')}<section class="settings-card">${captureToggle('systemAudio','Системный звук','Весь звук компьютера, в том числе при записи отдельного окна')}${captureRange('systemVolume','Громкость системного звука',0,100,'%')}${captureToggle('microphone','Микрофон','Смешивать голос со звуком компьютера')}${captureToggle('noiseSuppression','Шумоподавление микрофона','Подавлять постоянный фоновый шум при захвате голоса')}${captureToggle('echoCancellation','Убирать эхо','Уменьшать попадание звука из динамиков в микрофон')}${captureToggle('autoGainControl','Автогромкость микрофона','Автоматически выравнивать уровень голоса')}${captureRange('micVolume','Усиление микрофона',0,200,'%')}${captureSelect('audioBitrate','Качество звука','Битрейт звука в итоговом MP4',[[128,'128 кбит/с'],[192,'192 кбит/с'],[256,'256 кбит/с'],[320,'320 кбит/с']])}</section>${sectionTitle('ПОД ВАШ РИТМ','Поведение и горячие клавиши')}<section class="settings-card">${captureSelect('countdown','Обратный отсчёт','Время до начала захвата',[[0,'Без задержки'],[3,'3 секунды'],[5,'5 секунд'],[10,'10 секунд']])}${captureSelect('maxMinutes','Лимит длительности','Автоматически завершать запись',[[0,'Без лимита'],[5,'5 минут'],[15,'15 минут'],[30,'30 минут'],[60,'60 минут'],[120,'120 минут'],[180,'180 минут']])}${captureSelect('maxSizeMB','Лимит размера','Мягкая остановка после достижения размера',[[0,'Без лимита'],[512,'512 МБ'],[1024,'1 ГБ'],[2048,'2 ГБ'],[4096,'4 ГБ'],[8192,'8 ГБ']])}${captureSelect('hotkey','Начать / остановить','Глобальное сочетание клавиш',[['Alt+F9','Alt + F9'],['Control+Alt+R','Ctrl + Alt + R'],['Control+Shift+F9','Ctrl + Shift + F9']])}${captureSelect('panelHotkey','Панель записи','Открыть управление в островке',[['Alt+Z','Alt + Z'],['Control+Alt+Z','Ctrl + Alt + Z'],['Control+Shift+F8','Ctrl + Shift + F8']])}${captureToggle('excludeIsland','Не записывать островок','Исключить окно островка из захвата средствами Windows')}${captureToggle('hideSettings','Скрывать настройки при старте','Островок с кнопкой остановки остаётся доступен')}${captureToggle('showRecording','Управление во время записи','Кнопки появляются только после начала записи')}</section>${replaySettings()}${sectionTitle('ВАША ВИДЕОТЕКА','Файлы и последние записи')}<section class="settings-card"><div class="recording-folder"><div>${icon('folder')}<span data-record-folder>${esc(c.folder||'Папка «Видео» → EclipseIsland')}</span></div><button class="text-button" data-capture-folder>Выбрать папку</button><button class="text-button" data-capture-action="folder">Открыть папку</button></div><div data-recordings-list>${recordingsList()}</div></section>`;}
let captureSourceItems=[],captureSourceLoading=false,captureNotice=null,captureNoticeTimer;
function captureSourceChoice(){return choice('source','Источник записи',[['','Основной доступный экран'],...captureSourceItems.map(x=>[x.id,x.name])],captureConfig().source,{scope:'capture',disabled:recordingBusy()});}
function captureSourcesMarkup(){return captureSourceItems.slice(0,12).map(x=>`<button class="capture-source ${captureConfig().source===x.id?'selected':''}" data-capture-source="${esc(x.id)}" ${recordingBusy()?'disabled':''}>${/^data:image\//.test(x.thumbnail)?`<img src="${esc(x.thumbnail)}" alt="">`:''}<span>${esc(x.name)}</span></button>`).join('');}
async function loadCaptureSources(){if(captureSourceLoading||!api.captureSources)return;captureSourceLoading=true;try{captureSourceItems=await api.captureSources();if(!Array.isArray(captureSourceItems))captureSourceItems=[];const select=document.querySelector('[data-capture-source-control]');if(select){closeControls({restore:false});select.innerHTML=captureSourceChoice();syncControls(select);}const grid=document.querySelector('[data-capture-sources]');if(grid)grid.innerHTML=captureSourcesMarkup();}catch(error){toast(error.message||'Не удалось получить список экранов');}finally{captureSourceLoading=false;}}
async function saveCapture(patch){try{state.capture=await api.captureSettings(patch);updateCaptureDOM();}catch(error){toast(error.message||'Не удалось сохранить настройки записи');updateCaptureDOM();}}
function updateCaptureDOM(){
 updateReplayDOM();
 const c=captureConfig();document.querySelectorAll('[data-record-status]').forEach(el=>setText(el,recordingLabel()));document.querySelectorAll('[data-record-elapsed]').forEach(el=>setText(el,trackTime(state.capture?.elapsed)));document.querySelectorAll('[data-record-size]').forEach(el=>setText(el,sizeText(state.capture?.bytes)));
 document.querySelectorAll('[data-record-format]').forEach(el=>setText(el,state.capture?.width?`${state.capture.width} × ${state.capture.height} · цель ${state.capture.targetFPS} FPS${state.capture.sourceFPS?' · источник '+Math.round(state.capture.sourceFPS)+' FPS':''} · ${state.capture.codec||'захват'}${state.capture.videoBitrate?' · '+(state.capture.videoBitrate/1000000).toFixed(1)+' Мбит/с':''} → MP4`:`${c.height}p · ${c.fps} FPS · ${c.quality==='auto'?'автоматический битрейт':c.bitrate+' Мбит/с'}`));
 document.querySelectorAll('[data-record-error]').forEach(el=>setText(el,state.capture?.error||(state.capture?.warnings||[]).join(' · ')));
 document.querySelectorAll('[data-record-folder]').forEach(el=>setText(el,c.folder||'Папка «Видео» → EclipseIsland'));
 document.querySelectorAll('[data-record-shortcuts]').forEach(el=>setText(el,state.shortcuts?.record===false||state.shortcuts?.capturePanel===false?'Одна из горячих клавиш занята другим приложением. Выберите другое сочетание.':`${c.hotkey} — запись · ${c.panelHotkey} — панель`));
 document.querySelectorAll('[data-capture-buttons]').forEach(el=>{const key=state.capture?.status||'idle';if(el.dataset.status!==key){el.dataset.status=key;el.innerHTML=captureButtons();}});
 document.querySelectorAll('[data-capture-profile]').forEach(el=>{const id=el.dataset.captureProfile;el.setAttribute('aria-pressed',String(c.height===({eco:720,balanced:1080,quality:1440}[id])&&c.fps===({eco:30,balanced:60,quality:60}[id])));});
 document.querySelectorAll('[data-capture-source],[data-capture-refresh],[data-capture-folder],[data-capture-profile]').forEach(el=>el.disabled=recordingBusy());
 document.querySelectorAll('[data-capture-setting]').forEach(el=>{el.disabled=recordingBusy()||(el.dataset.captureSetting==='bitrate'&&c.quality==='auto')||(el.dataset.captureSetting==='replayBitrate'&&c.replayQuality==='auto');if(el===document.activeElement)return;const value=c[el.dataset.captureSetting];if(el.type==='checkbox')el.checked=!!value;else el.value=value;});
 syncControls();
 document.querySelectorAll('[data-capture-value]').forEach(el=>{const key=el.dataset.captureValue;setText(el,c[key]+(['bitrate','replayBitrate'].includes(key)?' Мбит/с':' %'));});
 document.querySelectorAll('[data-recordings-list]').forEach(el=>{const key=JSON.stringify((state.capture?.recent||[]).map(x=>x.id));if(el.dataset.ids!==key){el.dataset.ids=key;el.innerHTML=recordingsList(el.closest('.island')?3:24);}});
}
function replaySettings(){return `${sectionTitle('НЕ УПУСТИТЕ МОМЕНТ','Мгновенный повтор')}<section class="settings-card">${captureToggle('replayEnabled','Включить мгновенный повтор','Фоновая запись последних секунд. По умолчанию выключена')}${captureSelect('replaySeconds','Длина повтора','Сколько последних секунд сохранить',[[15,'15 секунд'],[30,'30 секунд'],[60,'1 минута'],[120,'2 минуты'],[180,'3 минуты'],[300,'5 минут'],[600,'10 минут']])}${captureSelect('replayHeight','Разрешение повтора','720p снижает нагрузку',[[720,'720p · экономно'],[1080,'1080p Full HD'],[1440,'1440p 2K']])}${captureSelect('replayFPS','FPS повтора','30 FPS для минимальной нагрузки',[[30,'30 FPS'],[60,'60 FPS'],[120,'120 FPS']])}${captureSelect('replayQuality','Качество повтора','Автоматический битрейт для выбранного разрешения и FPS',[['auto','Автоматически'],['manual','Вручную']])}${captureRange('replayBitrate','Ручной битрейт повтора',2,40,'Мбит/с')}${captureSelect('replayMaxMB','Лимит буфера на диске','Без лимита размера буфер ограничивается только выбранной длительностью',[[0,'Без лимита размера'],[128,'128 МБ'],[256,'256 МБ'],[512,'512 МБ'],[1024,'1 ГБ'],[2048,'2 ГБ'],[4096,'4 ГБ']])}${captureToggle('replaySystemAudio','Звук компьютера в повторе','Отдельная настройка для мгновенного повтора')}${captureRange('replaySystemVolume','Громкость компьютера в повторе',0,100,'%')}${captureToggle('replayMicrophone','Микрофон в повторе','Добавлять голос к фоновому захвату')}${captureToggle('replayNoiseSuppression','Шумоподавление микрофона','Уменьшать постоянный фоновый шум')}${captureToggle('replayEchoCancellation','Подавление эха','Убирать звук динамиков, попадающий в микрофон')}${captureToggle('replayAutoGainControl','Автогромкость голоса','Выравнивать уровень микрофона')}${captureToggle('replayMicHighPass','Убирать низкий гул','Фильтр микрофона ниже 80 Гц')}${captureToggle('replayMicCompressor','Сглаживать громкие пики','Компрессор голоса после усиления')}${captureRange('replayMicVolume','Усиление микрофона в повторе',0,200,'%')}${captureSelect('replayAudioBitrate','Качество звука повтора','Битрейт звуковой дорожки',[[128,'128 кбит/с'],[192,'192 кбит/с'],[256,'256 кбит/с'],[320,'320 кбит/с']])}${captureSelect('replayHotkey','Сохранить повтор','Работает из других приложений',[['Alt+F10','Alt + F10'],['Control+Alt+F10','Ctrl + Alt + F10'],['Control+Shift+F10','Ctrl + Shift + F10']])}<div class="recording-folder"><span data-replay-status></span><button class="button" data-capture-action="replay-save">${icon('record')} Сохранить повтор</button></div></section><div class="info-box">${icon('info')}<p>Повтор требует фонового захвата. Экономный профиль — 720p / 30 FPS. Буфер хранится на диске, старые фрагменты удаляются. Обычная запись временно приостанавливает повтор. Настройки звука повтора независимы от обычной записи. Изменение параметров перезапускает буфер; сохранённые видео остаются в папке.</p></div>`;}
function updateReplayDOM(){const r=state.replay||{},labels={off:'Выключен',starting:'Подключаем экран…',buffering:'Повтор включён',suspended:'Пауза на время обычной записи',error:'Повтор остановлен'};document.querySelectorAll('[data-replay-status]').forEach(el=>setText(el,r.error||((labels[r.status]||'Выключен')+(r.status==='buffering'?' · '+Math.floor(r.bufferSeconds||0)+' сек в буфере':'')+((r.warnings||[]).length?' · '+r.warnings.join(' · '):'')+(r.saving?' · Сохранение '+(r.saveProgress||0)+'%':''))));document.querySelectorAll('[data-capture-action="replay-save"]').forEach(el=>el.disabled=r.status!=='buffering'||r.saving);document.querySelectorAll('[data-replay-save-label]').forEach(el=>setText(el,r.saving?'Сохранение '+Math.round(r.saveProgress||0)+'%':'Сохранить повтор'));document.querySelectorAll('[data-replay-save-info]').forEach(el=>setText(el,r.status==='buffering'?trackTime(r.bufferSeconds||0)+' · '+captureConfig().replayHotkey.replaceAll('+',' + '):'Включите повтор в настройках'));}
function capturePanel(){return `<div class="island-capture"><div class="mini-record-state"><span class="record-dot ${recordingBusy()?'active':''}"></span><strong data-record-status>${recordingLabel()}</strong><span data-record-elapsed>${trackTime(state.capture?.elapsed)}</span></div><div data-capture-buttons>${captureButtons()}</div><button class="replay-save-primary" data-capture-action="replay-save">${icon('previous')}<strong data-replay-save-label>Сохранить повтор</strong><span data-replay-save-info></span></button><div class="mini-recordings" data-recordings-list>${recordingsList(3)}</div><div class="capture-panel-footer"><button class="text-button" data-capture-settings>Настройки записи</button><button class="text-button" data-capture-action="folder">${icon('folder')} Папка</button></div></div>`;}
function openToolPanel(panel){if(!document.querySelector(isOverlay?'.island':'.app-shell')){pendingToolPanel=panel;return;}if(isOverlay){tab=panel==='screenshots'?'screenshots':'launcher';expanded=true;renderIsland();}else{navigate(panel==='screenshots'?'screenshots':'launcher');if(panel==='launcher-processes')openProcessPicker();}}
function toolsState(){return state.tools||{entries:[],recent:[],settings:{copy:true,folder:''},busy:false};}
let launcherQuery='',processQuery='',processPickerOpen=false,processLoading=false,processRows=[],processError='';
function filteredLaunchers(){const q=launcherQuery.trim().toLocaleLowerCase();return (toolsState().entries||[]).filter(x=>!q||(x.name+' '+x.target).toLocaleLowerCase().includes(q));}
function launcherSearch(){return `<label class="launcher-search">${icon('search')}<input data-launcher-search value="${esc(launcherQuery)}" placeholder="Найти приложение или папку…" aria-label="Поиск в быстром запуске"></label>`;}
function runAllButton(){return `<button class="button launcher-run-all" data-launcher-action="open-all" ${(toolsState().entries||[]).length&&!toolsState().launchingAll?'':'disabled'}>${icon('play')}<span data-launcher-run-label>Запустить всё (${(toolsState().entries||[]).length})</span></button>`;}
function processSection(){return `<section class="settings-card process-picker" data-process-panel ${processPickerOpen?'':'hidden'}><div class="process-title"><strong>Добавить из процессов</strong><button class="text-button" data-process-refresh>Обновить</button><button class="icon-button" data-process-close aria-label="Закрыть список">${icon('close')}</button></div><label class="launcher-search">${icon('search')}<input data-process-search value="${esc(processQuery)}" placeholder="Поиск по названию, окну или пути…" aria-label="Поиск процессов"></label><div data-process-list></div><small>Показаны доступные приложения с путём EXE. Несколько процессов одного приложения объединены.</small></section>`;}
function renderProcesses(){const panel=document.querySelector('[data-process-panel]');if(!panel)return;panel.hidden=!processPickerOpen;const list=panel.querySelector('[data-process-list]');if(processLoading){list.innerHTML='<div class="tools-empty">Читаем список процессов…</div>';return;}const q=processQuery.trim().toLocaleLowerCase(),items=processRows.filter(x=>!q||(x.name+' '+x.title+' '+x.target).toLocaleLowerCase().includes(q));const targets=(toolsState().entries||[]).map(x=>x.target.toLocaleLowerCase());list.innerHTML=processError?`<div class="tools-empty">${esc(processError)}</div>`:items.length?items.map(item=>`<div class="process-row"><span>${icon('rocket')}</span><div><strong>${esc(item.name)}</strong><small>${esc(item.title||item.target)}</small><small title="${esc(item.target)}">${esc(item.target)}</small></div><button class="text-button" data-launcher-action="add-process" data-entry-id="${esc(item.id)}" ${targets.includes(item.target.toLocaleLowerCase())?'disabled':''}>${targets.includes(item.target.toLocaleLowerCase())?'Добавлено':'Добавить'}</button></div>`).join(''):'<div class="tools-empty">Ничего не найдено</div>';}
async function openProcessPicker(refresh=true){if(isOverlay){api.showSettings('launcher-processes');return;}processPickerOpen=true;processLoading=refresh;processError='';renderProcesses();document.querySelector('[data-process-search]')?.focus();if(!refresh)return;try{const result=await api.launcherProcesses();if(!result.ok)throw Error(result.error);processRows=result.items||[];}catch(error){processError=error.message;}finally{processLoading=false;renderProcesses();}}
function toolSelect(key,title,description,options){return `<div class="setting-row"><span class="setting-icon">${icon('camera')}</span><span class="setting-copy"><strong>${title}</strong><small>${description}</small></span>${choice(key,title,options,toolsState().settings?.[key]??({format:'png',maxHeight:0,countdown:0,monitor:'cursor'})[key],{scope:'tools',disabled:!!toolsState().busy})}</div>`;}
function toolToggle(key,title,description,defaultValue=true){return `<label class="setting-row"><span class="setting-icon">${icon('check')}</span><span class="setting-copy"><strong>${title}</strong><small>${description}</small></span><input class="toggle" type="checkbox" data-tools-setting="${key}" ${(toolsState().settings?.[key]??defaultValue)?'checked':''}></label>`;}

function launcherTiles(){const items=filteredLaunchers();return items.length?items.map(item=>`<button class="launcher-tile" data-launcher-action="open" data-entry-id="${esc(item.id)}" title="${esc(item.name)}"><span>${item.icon?`<img src="${esc(item.icon)}" alt="">`:icon(item.kind==='folder'?'folder':'rocket')}</span><strong>${esc(item.name)}</strong></button>`).join(''):'<div class="tools-empty">Приложения и папки — в одном нажатии.<br><small>Добавьте первые ярлыки кнопками ниже.</small></div>';}
function launcherRows(){const items=filteredLaunchers();return items.map((item,index)=>`<div class="launcher-row"><button class="icon-button" data-launcher-action="open" data-entry-id="${esc(item.id)}" aria-label="Открыть ${esc(item.name)}">${icon(item.kind==='folder'?'folder':'rocket')}</button><div><input data-launcher-name="${esc(item.id)}" value="${esc(item.name)}" maxlength="80" aria-label="Название ярлыка"><small title="${esc(item.target)}">${esc(item.target)}</small></div><button class="icon-button" data-launcher-action="move" data-direction="-1" data-entry-id="${esc(item.id)}" aria-label="Выше" ${(toolsState().entries||[]).findIndex(x=>x.id===item.id)===0?'disabled':''}>${icon('chevronUp')}</button><button class="icon-button" data-launcher-action="move" data-direction="1" data-entry-id="${esc(item.id)}" aria-label="Ниже" ${(toolsState().entries||[]).findIndex(x=>x.id===item.id)===(toolsState().entries||[]).length-1?'disabled':''}>${icon('chevronDown')}</button><button class="icon-button" data-launcher-action="remove" data-entry-id="${esc(item.id)}" aria-label="Убрать ярлык">${icon('trash')}</button></div>`).join('')||'<div class="tools-empty">Пока нет ярлыков. Добавьте приложение или папку.</div>';}
function launcherAdd(){return `<div class="tools-footer"><button class="text-button" data-launcher-action="add" data-entry-kind="app">${icon('plus')} Приложение</button><button class="text-button" data-launcher-action="add" data-entry-kind="folder">${icon('folder')} Папка</button><button class="text-button" data-process-open>${icon('grid')} Из процессов</button><span data-tools-shortcut="launcher"></span></div>`;}
function launcherPanel(){return `${launcherSearch()}<div class="launcher-grid" data-launcher-grid>${launcherTiles()}</div>${runAllButton()}${launcherAdd()}`;}
function launcherPage(){return `<div class="feature-banner"><div class="feature-icon">${icon('rocket')}</div><div><span class="eyebrow">НА РАССТОЯНИИ КАСАНИЯ</span><h2>Ваш быстрый запуск.</h2><p>Приложения, ярлыки и папки прямо в островке.</p></div></div><section class="settings-card tools-settings">${launcherSearch()}<div data-launcher-list>${launcherRows()}</div>${runAllButton()}${launcherAdd()}</section>${processSection()}<div class="info-box">${icon('info')}<p>До 24 ярлыков. Измените название в поле, расположите кнопками со стрелками. Удаление ярлыка из списка сохраняет приложение на компьютере. Ctrl + Alt + L открывает вкладку запуска.</p></div>`;}
function screenshotButtons(){return `<div class="screenshot-actions"><button class="button capture-start" data-shot-action="area">${icon('crop')} Выделить область</button><button class="button" data-shot-action="screen">${icon('monitor')} Весь экран</button><button class="text-button" data-shot-action="cancel" hidden>Отмена</button></div><p class="shot-status" data-shot-status></p>`;}
function screenshotRows(limit=24){const items=(toolsState().recent||[]).slice(0,limit);return items.length?items.map(item=>`<div class="shot-row"><button class="shot-thumbnail" data-shot-action="open" data-shot-id="${esc(item.id)}" title="Открыть скриншот">${item.thumbnail?`<img src="${esc(item.thumbnail)}" alt="Скриншот">`:icon('camera')}</button><div><strong>${new Date(item.createdAt).toLocaleString('ru-RU')}</strong><small>${esc(item.width)} × ${esc(item.height)} · ${esc(String(item.format||(/\.jpe?g$/i.test(item.file||'')?'jpg':'png')).toUpperCase())}</small></div><button class="icon-button" data-shot-action="copy" data-shot-id="${esc(item.id)}" aria-label="Скопировать картинку" title="Скопировать">${icon('copy')}</button><button class="icon-button" data-shot-action="reveal" data-shot-id="${esc(item.id)}" aria-label="Показать в папке" title="Показать в папке">${icon('folder')}</button></div>`).join(''):'<div class="tools-empty">Сохраняйте моменты без лишних окон.<br><small>Выделите область или снимите весь монитор.</small></div>';}
function screenshotPanel(){return `${screenshotButtons()}<div class="shot-history compact" data-shot-history data-shot-limit="3">${screenshotRows(3)}</div><div class="tools-footer"><button class="text-button" data-shot-action="folder">${icon('folder')} Папка</button><button class="text-button" data-tools-settings="screenshots">Настройки</button></div>`;}
function screenshotPage(){const t=toolsState();return `<div class="feature-banner"><div class="feature-icon">${icon('camera')}</div><div><span class="eyebrow">СОХРАНИТЕ НУЖНОЕ</span><h2>Снимок одним движением.</h2><p>Область или монитор. Качество и поведение — под вас.</p></div></div><section class="settings-card tools-settings">${screenshotButtons()}${toolSelect('format','Формат','PNG — без потерь; JPEG — меньше размер файла',[['png','PNG · без потерь'],['jpg','JPEG · компактнее']])}<label class="setting-row"><span class="setting-icon">${icon('sliders')}</span><span class="setting-copy"><strong>Качество JPEG</strong><small>Используется при сохранении в JPEG</small></span><output data-tools-quality>90%</output><input class="capture-range" type="range" min="50" max="100" value="${t.settings?.quality||90}" data-tools-setting="quality"></label>${toolSelect('maxHeight','Размер изображения','Пропорции сохраняются. Маленькие снимки не растягиваются',[[0,'Исходный размер'],[720,'До 720p'],[1080,'До 1080p'],[1440,'До 1440p · 2K'],[2160,'До 2160p · 4K']])}${toolSelect('monitor','Монитор','Для выделения и снимка всего экрана',[['cursor','Под курсором'],['primary','Основной'],...(state.monitors||[]).map(x=>[x.id,x.label])])}${toolSelect('countdown','Задержка','Время подготовить экран',[[0,'Без задержки'],[3,'3 секунды'],[5,'5 секунд'],[10,'10 секунд']])}${toolToggle('showCursor','Показывать курсор мыши','Выключите, чтобы сохранять скриншоты без указателя')}${toolToggle('excludeIsland','Скрывать островок в кадре','Выключите, чтобы не убирать видимый островок из кадра')}${toolToggle('hideSettings','Скрывать окно настроек','Временно исключать настройки из кадра')}${toolToggle('notifications','Уведомление в островке','Показывать короткое подтверждение после сохранения')}${toolToggle('openAfter','Открывать после сохранения','Показывать снимок во встроенном просмотре',false)}<label class="setting-row"><span class="setting-icon">${icon('copy')}</span><span class="setting-copy"><strong>Копировать в буфер</strong><small>Картинка также сохраняется в выбранную папку</small></span><input class="toggle" type="checkbox" data-tools-copy ${t.settings?.copy!==false?'checked':''}></label><div class="shot-folder"><span data-shot-folder>${esc(t.settings?.folder||'Изображения / EclipseIsland')}</span><button class="text-button" data-shot-folder-change>Изменить папку</button><button class="icon-button" data-shot-action="folder" aria-label="Открыть папку">${icon('folder')}</button></div><div class="tools-shortcuts"><span data-tools-shortcut="screenshotArea"></span><span data-tools-shortcut="screenshotScreen"></span></div></section>${sectionTitle('ВСЁ ПОД РУКОЙ','Последние скриншоты')}<section class="settings-card" data-shot-history>${screenshotRows()}</section><div class="info-box">${icon('info')}<p>Потяните мышью и отпустите для сохранения. Esc или правая кнопка — отмена. Снимки открываются во встроенном просмотре; при его закрытии состояние островка восстанавливается. Последние 24 снимка доступны здесь, остальные файлы остаются в папке.</p></div>`;}
function updateTools(){
 const t=toolsState(),entries=JSON.stringify([t.entries||[],launcherQuery]),shots=JSON.stringify(t.recent||[]);
 document.querySelectorAll('[data-launcher-grid],[data-launcher-list]').forEach(el=>{if(el.dataset.key!==entries){el.dataset.key=entries;el.innerHTML=el.hasAttribute('data-launcher-grid')?launcherTiles():launcherRows();}});
 document.querySelectorAll('[data-shot-history]').forEach(el=>{if(el.dataset.key!==shots){el.dataset.key=shots;el.innerHTML=screenshotRows(Number(el.dataset.shotLimit)||24);}});
 document.querySelectorAll('[data-shot-action="area"],[data-shot-action="screen"]').forEach(el=>el.disabled=!!t.busy);
 document.querySelectorAll('[data-shot-status]').forEach(el=>setText(el,t.busy?(t.remaining?'Снимок через '+t.remaining+'…':'Создаём снимок…'):t.error||'Ctrl + Alt + S · область / Ctrl + Alt + P · экран'));
 document.querySelectorAll('[data-launcher-action="open-all"]').forEach(el=>{el.disabled=!(t.entries||[]).length||!!t.launchingAll;setText(el.querySelector('[data-launcher-run-label]'),t.launchingAll?'Запускаем…':'Запустить всё ('+(t.entries||[]).length+')');});
 document.querySelectorAll('[data-tools-setting]').forEach(el=>{const key=el.dataset.toolsSetting;if(el.type==='checkbox')el.checked=t.settings?.[key]??(key!=='openAfter');else if(t.settings?.[key]!==undefined&&document.activeElement!==el)el.value=String(t.settings[key]);el.disabled=!!t.busy||(key==='quality'&&(t.settings?.format||'png')!=='jpg');});
 document.querySelectorAll('[data-tools-quality]').forEach(el=>setText(el,(t.settings?.quality||90)+'%'));syncControls();renderProcesses();
 document.querySelectorAll('[data-shot-action="cancel"]').forEach(el=>el.hidden=!t.busy);
 document.querySelectorAll('[data-tools-copy]').forEach(el=>el.checked=t.settings?.copy!==false);
 document.querySelectorAll('[data-shot-folder]').forEach(el=>setText(el,t.settings?.folder||'Изображения / EclipseIsland'));
 const keys={launcher:'Ctrl + Alt + L',screenshotArea:'Ctrl + Alt + S · область',screenshotScreen:'Ctrl + Alt + P · экран'};
 document.querySelectorAll('[data-tools-shortcut]').forEach(el=>setText(el,keys[el.dataset.toolsShortcut]+(state.shortcuts?.[el.dataset.toolsShortcut]===false?' · сочетание занято':'')));
}

function activeDownloads(){return state.settings.showDownloads!==false?(state.downloads?.items||[]).filter(item=>!item.complete):[];}
function recentDownloadNotice(){return state.settings.showDownloads?(state.downloads?.recent||[]).find(item=>Date.now()-(item.createdAt||0)<4500)||null:null;}
function visibleTransfers(){return state.settings.showTransfers?(state.transfers?.items||[]):[];}
function transferCard(item){return `<section class="transfer-card" data-operation-id="${esc(item.id)}"><div class="transfer-top"><span class="transfer-symbol">${icon(item.kind==='delete'?'trash':'folder')}</span><div class="transfer-copy"><strong data-transfer-title></strong><small data-transfer-detail></small></div><span data-transfer-percent></span><button class="icon-button" data-transfer-action="pause" data-transfer-id="${esc(item.id)}" aria-label="Пауза операции">${icon('pause')}</button><button class="icon-button" data-transfer-action="cancel" data-transfer-id="${esc(item.id)}" aria-label="Отменить операцию">${icon('close')}</button><button class="icon-button native-transfer" data-transfer-action="show" data-transfer-id="${esc(item.id)}" aria-label="Вернуть окно Windows">${icon('arrowUp')}</button></div><div class="transfer-meter"><i></i></div></section>`;}
function updateTransferContainer(container,items){
 const key=items.map(x=>x.id+':'+x.kind).join('|');if(container.dataset.ids!==key){container.dataset.ids=key;container.innerHTML=items.map(transferCard).join('');}
 for(const item of items){const row=[...container.children].find(x=>x.dataset.operationId===item.id);if(!row)continue;
 setText(row.querySelector('[data-transfer-title]'),item.title||'Операция с файлами');setText(row.querySelector('[data-transfer-detail]'),item.attention?'Требуется решение в Windows':item.nativeOnly?'Управление в системном окне':item.details||'Подготовка…');
 row.querySelector('[data-transfer-detail]').hidden=state.settings.transferDetails===false&&!item.attention;setText(row.querySelector('[data-transfer-percent]'),item.paused?'Пауза':item.percent===null?'…':Math.round(item.percent)+'%');setClass(row,'is-indeterminate',item.percent===null);setClass(row,'is-paused',item.paused);
 row.querySelector('.transfer-meter i').style.transform=item.percent===null?'':'scaleX('+Math.max(0,Math.min(1,item.percent/100))+')';
 const pause=row.querySelector('[data-transfer-action="pause"]');pause.disabled=!item.canPause;if(pause.dataset.paused!==String(item.paused)){pause.dataset.paused=String(item.paused);pause.innerHTML=icon(item.paused?'play':'pause');pause.setAttribute('aria-label',item.paused?'Продолжить операцию':'Пауза операции');}row.querySelector('[data-transfer-action="cancel"]').disabled=!item.canCancel;
 }
}
let activityAckFrame;
function requestActivityHeartbeat(){
 if(!isOverlay||activityAckFrame||!nativeVisible||!state.settings.enabled||!state.settings.showTransfers||!state.settings.replaceTransferWindow||!visibleTransfers().length)return;
 activityAckFrame=requestAnimationFrame(()=>{activityAckFrame=0;if(nativeVisible&&state.settings.enabled&&!document.documentElement.classList.contains('overlay-concealed'))api.activityHeartbeat?.([...document.querySelectorAll('[data-transfer-band] [data-transfer-id]')].map(x=>x.dataset.transferId).filter((x,i,a)=>a.indexOf(x)===i));});
}
function updateTransfers(){
 const items=visibleTransfers(),band=document.querySelector('[data-transfer-band]'),island=document.querySelector('.island');
 if(band&&island){const visible=items.slice(0,2),key=visible.map(x=>x.id).join('|'),changed=band.dataset.structure!==key;band.dataset.structure=key;setClass(island,'has-transfers',!!visible.length);island.style.setProperty('--transfer-height',(visible.length?visible.length*76+7:0)+'px');updateTransferContainer(band,visible);if(changed){reportBoundsDuringTransition();requestActivityHeartbeat();}}
 document.querySelectorAll('[data-transfer-error]').forEach(el=>setText(el,state.transfers?.error||''));
 document.querySelectorAll('[data-transfer-list]').forEach(el=>updateTransferContainer(el,items));
}
function completionSettings(){const choices=[['soft','Мягкий'],['chime','Колокольчики'],['digital','Цифровой']];return `${sectionTitle('ЗВУКИ','Завершение операций')}<section class="settings-card">${toggleRow('downloadSound','Звук загрузки','Когда файл сохранён (включая Telegram и AyuGram)','volume')}${toggleRow('transferSound','Звук передачи файлов','Когда копирование или перемещение достигло 100%','volume')}${rangeRow('completionVolume','Громкость уведомлений','Независимо от звуков интерфейса',0,100,'volume')}${['download','transfer'].map(kind=>`<div class="setting-row"><span class="setting-icon">${icon('music')}</span><span class="setting-copy"><strong>${kind==='download'?'Мелодия загрузки':'Мелодия передачи'}</strong></span>${choice(kind+'Tone','Мелодия',choices,state.settings[kind+'Tone'])}<button class="icon-button" data-completion-preview="${kind}" title="Прослушать" aria-label="Прослушать мелодию">${icon('play')}</button></div>`).join('')}</section>`;}
function transfersPage(){return `<div class="feature-banner"><div class="feature-icon">${icon('folder')}</div><div><span class="eyebrow">ОПЕРАЦИИ И ЗАГРУЗКИ</span><h2>Прогресс на поверхности.</h2><p>Копирование, перемещение, удаление и новые загрузки — рядом с островком.</p></div></div><section class="settings-card">${toggleRow('showTransfers','Операции с файлами','Показывать прогресс копирования, перемещения и удаления в островке','folder')}${toggleRow('replaceTransferWindow','Скрывать системное окно','Включено — скрывать оригинальный прогресс Windows. Выключено — показывать оба окна','layers')}${toggleRow('transferDetails','Подробности','Названия, количество файлов и скорость из Проводника','info')}${toggleRow('showDownloads','Загрузки','Отслеживать загрузки и файлы Telegram в известных папках','folder')}</section><div class="info-box">${icon('info')}<p>Скрытие системного окна включается отдельно. На старте или при завершении операции оно может кратко появляться. При ошибке, запросе подтверждения или потере связи системное окно возвращается. Загрузки определяются по росту файлов в папке загрузок и известных папках Telegram. Общий размер не всегда доступен: показываются скачанные байты и приблизительная скорость.</p></div><p class="capture-error" data-transfer-error></p><section class="settings-card" data-transfer-list></section>${completionSettings()}`;}
let downloadNoticeTimer;
function updateActivities(){
 updateTransfers();
 const enabled=recordingBusy()&&captureConfig().showRecording,notice=!recordingBusy()&&captureNotice&&captureNotice.until>Date.now()?captureNotice:null;
 const download=activeDownloads()[0]||null,downloadNotice=download?null:recentDownloadNotice();clearTimeout(downloadNoticeTimer);if(downloadNotice)downloadNoticeTimer=setTimeout(updateActivities,Math.max(20,4500-(Date.now()-downloadNotice.createdAt)+20));
 const band=document.querySelector('[data-activity-band]'),island=document.querySelector('.island');
 if(band&&island){const previous=island.classList.contains('has-activity'),show=enabled||notice||download||downloadNotice;island.classList.toggle('has-activity',!!show);island.style.setProperty('--activity-height',(enabled?46:0)+(notice?40:0)+(download?44:0)+(downloadNotice?40:0)+'px');
 const status=state.capture?.status||'idle',busy=recordingBusy(),pausable=['recording','paused'].includes(status),saving=['stopping','exporting'].includes(status),latest=state.capture?.recent?.[0];
 const key=[status,!!busy,latest?.id,notice?.text,notice?.id,enabled,download?.id,download?.details,downloadNotice?.id].join('|');
 if(band.dataset.key!==key){band.dataset.key=key;band.innerHTML=(enabled?`<div class="activity-row recording-toolbar"><span class="toolbar-state" role="status" title="${esc(recordingLabel())}"><span class="record-dot ${busy?'active':''}"></span><span data-toolbar-time>${busy?trackTime(state.capture?.elapsed):'Запись'}</span></span><div class="toolbar-buttons">${busy?`<button class="icon-button" data-capture-action="pause" aria-label="${status==='paused'?'Продолжить запись':'Пауза записи'}" title="${status==='paused'?'Продолжить':'Пауза'}" ${!pausable?'disabled':''}>${icon(status==='paused'?'play':'pause')}</button><button class="icon-button toolbar-stop" data-capture-action="stop" aria-label="Остановить запись" title="${saving?'Сохраняем видео…':'Остановить'}" ${saving?'disabled':''}>${icon('stop')}</button>`:`<button class="icon-button toolbar-start" data-capture-action="start" aria-label="Начать запись" title="Начать запись">${icon('record')}</button>`}<button class="icon-button" data-capture-action="preview" ${latest?'data-recording-id="'+esc(latest.id)+'"':'disabled'} aria-label="Последнее видео" title="Последнее видео">${icon('play')}</button><button class="icon-button" data-capture-action="folder" aria-label="Открыть папку записей" title="Папка записей">${icon('folder')}</button><button class="icon-button" data-capture-settings aria-label="Настройки записи" title="Настройки записи">${icon('sliders')}</button></div></div>`:'')+(notice?`<div class="activity-row capture-notice"><button ${notice.error?'data-capture-settings':notice.kind==='screenshot'?'data-shot-action="open" data-shot-id="'+esc(notice.id)+'"':'data-capture-action="preview" data-recording-id="'+esc(notice.id)+'"'}>${icon(notice.error?'info':'check')}<strong>${esc(notice.text)}</strong>${icon('arrow')}</button></div>`:'')+(download?`<div class="activity-row download-row"><button data-download-action="${download.file?'reveal':'open-folder'}" ${download.id?`data-download-id="${esc(download.id)}"`:''}>${icon('folder')}<strong>${esc(download.title)}</strong><span>${esc(download.details||'Загрузка')}</span></button><button class="icon-button" data-download-action="open-folder" aria-label="Открыть папку Загрузки" title="Папка Загрузки">${icon('arrowUp')}</button><div class="activity-progress indeterminate" aria-hidden="true"><i style="width:32%"></i></div></div>`:'')+(downloadNotice?`<div class="activity-row capture-notice"><button data-download-action="${downloadNotice.file?'reveal':'open-folder'}" ${downloadNotice.id?`data-download-id="${esc(downloadNotice.id)}"`:''}>${icon('folder')}<strong>${esc(downloadNotice.text||downloadNotice.title||'Загрузка завершена')}</strong>${icon('arrow')}</button></div>`:'');}
 setText(band.querySelector('[data-toolbar-time]'),status==='exporting'?'MP4 '+Math.round(state.capture?.exportProgress||0)+'%':busy?trackTime(state.capture?.elapsed):'Запись');
 if(previous!==!!show||band.dataset.height!==island.style.getPropertyValue('--activity-height')){band.dataset.height=island.style.getPropertyValue('--activity-height');reportBoundsDuringTransition();}}
 updateCaptureDOM();
}

function musicPage(){return `<div class="feature-banner"><div class="feature-icon">${icon('headphones')}</div><div><span class="eyebrow">ВАШ ЛИЧНЫЙ САУНДТРЕК</span><h2>Музыка всегда рядом.</h2><p>Переключайте треки, ставьте на паузу<br>и возвращайтесь к любимым моментам.</p></div><div class="banner-wave">${Array.from({length:17},(_,i)=>`<i style="--h:${18+Math.sin(i*.9)**2*58}px;--d:${i*.07}s"></i>`).join('')}</div></div><section class="settings-card music-detail">${musicControls(true)}</section>${sectionTitle('БЕЗ ЛИШНИХ ДВИЖЕНИЙ','Управление музыкой')}<section class="settings-card">${mediaSourceRow()}${toggleRow('showMusic','Музыка в острове','Название трека и управление воспроизведением','music')}</section><div class="info-box">${icon('info')}<p>EclipseIsland подключается к системной медиасессии Windows. Возможности зависят от плеера: некоторые приложения не передают длительность трека или не поддерживают перемотку.</p></div>`;}
function weatherPage(){return `<div class="weather-detail" data-weather-detail></div>${sectionTitle('БЛИЖЕ К ДОМУ','Ваш город')}<section class="settings-card city-card"><label class="search-field">${icon('search')}<input id="city-search" placeholder="Начните вводить город…" autocomplete="off" aria-label="Поиск города"><span class="search-shortcut">⌕</span></label><div id="city-results" aria-live="polite"></div><div class="selected-city">${icon('pin')}<div><strong data-city-label>${esc(state.settings.city?.name||'Город ещё не выбран')}</strong><small>${esc(state.settings.city?.country||'Местоположение выбираете только вы')}</small></div><button class="icon-button" data-refresh-weather aria-label="Обновить погоду">${icon('refresh')}</button></div></section><section class="settings-card weather-toggle">${toggleRow('showWeather','Погода в острове','Температура и небо за окном — одним взглядом','sun')}</section><div class="weather-credit">Данные <a href="https://open-meteo.com/" target="_blank" rel="noreferrer">Open-Meteo</a> · Обновление каждые 15 минут</div>`;}
function shortcutsPage(){const browser=state.platform==='browser';return `<div class="feature-banner"><div class="feature-icon">${icon('keyboard')}</div><div><span class="eyebrow">ПРИВЫЧНО. МГНОВЕННО.</span><h2>Всё под рукой.</h2><p>Пара клавиш — и вы уже там,<br>где нужно.</p></div></div><section class="settings-card shortcuts-card">${[['Раскрыть или свернуть остров','Не отвлекаясь от текущего приложения',['Ctrl','Alt','Space'],state.shortcuts.expand],['Показать или скрыть остров','Освободите экран одним движением',['Ctrl','Alt','I'],state.shortcuts.visibility],['Быстрый запуск','Открыть вкладку с приложениями и папками',['Ctrl','Alt','L'],state.shortcuts.launcher],['Скриншот области','Выделить область на мониторе под курсором',['Ctrl','Alt','S'],state.shortcuts.screenshotArea],['Скриншот экрана','Сохранить монитор под курсором',['Ctrl','Alt','P'],state.shortcuts.screenshotScreen],['Предыдущий трек','Переключить музыку назад',['Ctrl','Alt','←'],state.shortcuts.mediaPrevious],['Следующий трек','Переключить музыку вперёд',['Ctrl','Alt','→'],state.shortcuts.mediaNext],['Пауза / воспроизведение','Остановить или продолжить текущий трек',['Ctrl','Alt','↓'],state.shortcuts.mediaPause],['Свернуть раскрытый остров','Когда нужное уже под рукой',['Esc'],true]].map(([title,desc,keys,ok])=>`<div class="setting-row"><span class="setting-copy"><strong>${title}</strong><small>${desc}${!ok&&!browser?' · Сочетание занято другим приложением':''}</small></span><div class="key-combo">${keys.map(k=>`<kbd>${k}</kbd>`).join('<span>+</span>')}</div></div>`).join('')}</section><div class="info-box">${icon('info')}<p>${browser?'Глобальные горячие клавиши работают в настольном приложении Windows.':'Сочетания Ctrl + Alt работают глобально. Esc сворачивает остров, когда его окно получает нажатие. Если игра перехватывает клавиши, используйте значок EclipseIsland в трее.'}</p></div><div class="gesture-card"><span class="gesture-icon">${icon('spark')}</span><h3>Можно и без клавиатуры</h3><p>Наведите курсор или нажмите на остров,<br>чтобы открыть больше возможностей.</p></div>`;}
function aboutPage(){return `<div class="about-card"><div class="about-logo" aria-hidden="true">${icon('spark')}</div><h2>EclipseIsland<span class="version">${esc(state.version||'1.0.2')}</span></h2><p>Чуть меньше шума.<br>Чуть больше вашего.</p><span class="tag">Windows 10 / 11</span></div><section class="settings-card">${toggleRow('enabled','Показывать остров','Всегда рядом, когда нужен','layers')}</section><div class="info-box">${icon('info')}<p>Для игр используйте оконный режим без рамки. В эксклюзивном полноэкранном режиме оверлей может быть скрыт. EclipseIsland использует обычное окно Windows и не внедряется в процессы игр.</p></div><button class="button danger" data-quit>${icon('power')} Выйти из EclipseIsland</button>`;}
function renderShell(){
  if(isOverlay){document.body.classList.add('overlay-mode');app.innerHTML='<main class="overlay-root"><div class="island-mount"></div></main>';return;}
  app.innerHTML=`<div class="app-shell"><aside class="sidebar"><div class="brand"><span class="brand-logo" aria-hidden="true">${icon('spark')}</span><span>EclipseIsland</span></div><div class="sidebar-section-label">ВАШЕ ПРОСТРАНСТВО</div><nav>${nav.map(([id,ico,label])=>`<button class="nav-item ${id===page?'active':''}" data-nav="${id}">${icon(ico)}<span>${label}</span>${id==='overview'?'<span class="nav-dot"></span>':''}</button>`).join('')}</nav><div class="sidebar-bottom"><div class="sidebar-tip"><span class="tip-graphic brand-logo-mini">${icon('spark')}</span><strong>Всегда рядом.<br>Никогда не мешает.</strong><p>Маленький остров<br>в большом мире.</p></div><button class="nav-item" data-nav="about">${icon('info')}<span>Об EclipseIsland</span><span class="sidebar-version">v${esc(state.version||'1.0.2')}</span></button></div></aside><div class="workspace"><div class="window-bar"><span>${icon('spark')} ECLIPSEISLAND / НАСТРОЙКИ</span><div class="window-actions"><button data-minimize aria-label="Свернуть окно">${icon('minus')}</button><button data-close aria-label="Скрыть настройки">${icon('close')}</button></div></div><main class="content-scroll"><header class="page-header"><div><div class="breadcrumb">ЛИЧНОЕ ПРОСТРАНСТВО <span>/</span> <span id="breadcrumb-page">Обзор</span></div><h1 id="page-title">Обзор</h1><p id="page-subtitle">Всё важное. На поверхности.</p></div><span class="status-badge" data-enabled-status></span></header><div id="page-content"></div><footer class="page-footer"><span><span class="footer-brand">${icon('spark')} EclipseIsland</span> Немного спокойствия на вашем экране.</span><span class="save-status">${icon('check')} Сохраняется автоматически</span></footer></main></div></div>`;
}
function renderPage(){if(isOverlay)return;const [title,subtitle]=titles[page];document.querySelector('#page-title').textContent=title;document.querySelector('#page-subtitle').textContent=subtitle;document.querySelector('#breadcrumb-page').textContent=title;document.querySelectorAll('[data-nav]').forEach(el=>el.classList.toggle('active',el.dataset.nav===page && el.classList.contains('nav-item')));document.querySelector('#page-content').innerHTML=({overview,appearance,music:musicPage,weather:weatherPage,capture:capturePage,launcher:launcherPage,screenshots:screenshotPage,transfers:transfersPage,shortcuts:shortcutsPage,about:aboutPage})[page]();renderIsland();applySettings();updateLive();document.querySelectorAll('#page-content>.widgets>.widget,#page-content>.settings-card,#page-content>.feature-banner,#page-content>.preview-card').forEach((el,index)=>{el.classList.add('enter-card');el.style.setProperty('--enter-delay',`${Math.min(index,5)*25}ms`);});}
function navigate(next){if(!titles[next])return;closeControls({restore:false});page=next;expanded=false;renderPage();document.querySelector('.content-scroll')?.scrollTo({top:0});if(next==='capture')loadCaptureSources();}
function compactIdleRight(hasWeather,w,s){return hasWeather?`${icon(weatherIcon(w.code,w.isDay))}<span>${Math.round(w.temperature)}°</span>`:'<span data-short-date></span>';}
function todayPanelMarkup(hasWeather,w,s){return `<div class="today-panel"><div><span class="eyebrow">ВАШ МОМЕНТ</span><span class="island-big-time" data-clock></span><span data-date></span></div><div class="today-orb">${icon(hasWeather?weatherIcon(w.code,w.isDay):'spark')}${hasWeather?`<strong>${Math.round(w.temperature)}°</strong><span>${esc(w.city)}</span>`:'<span>Хорошего дня</span>'}</div></div>`;}
function islandMarkup(){const m=state.media,w=state.weather,s=state.settings;const hasWeather=s.showWeather&&w.status==='ready';const playing=s.showMusic&&m.active;return `<article data-renderer="${state.settings.islandRenderer}" class="island ${expanded?'expanded':''} ${['capture','launcher','screenshots'].includes(tab)?'is-activity-panel':''} ${m.playing&&s.showMusic?'is-playing':''}" aria-label="EclipseIsland"><div class="transfer-band" data-transfer-band></div><button class="island-compact" data-expand aria-label="${expanded?'Свернуть':'Раскрыть'} остров" aria-expanded="${expanded}"><span class="compact-left">${playing?`<span class="compact-art" data-artwork>${icon('music')}</span><span class="compact-track">${esc(m.title||'Без названия')}</span>`:`<span class="island-spark">${icon('spark')}</span><span class="compact-clock" data-clock></span>`}</span><span class="compact-right">${playing?'<span class="equalizer" data-equalizer><i></i><i></i><i></i><i></i></span>':compactIdleRight(hasWeather,w,s)}</span></button><div class="activity-band" data-activity-band></div><div class="island-expanded" ${expanded?'':'inert'}><div class="island-tabs"><button data-island-tab="today" class="${tab==='today'?'active':''}">${icon('grid')} Сегодня</button>${s.showMusic?`<button data-island-tab="music" class="${tab==='music'?'active':''}">${icon('music')} Музыка</button>`:''}${s.showWeather?`<button data-island-tab="weather" class="${tab==='weather'?'active':''}">${icon('sun')} Погода</button>`:''}<button data-island-tab="capture" class="${tab==='capture'?'active':''}">${icon('record')} Запись</button><button data-island-tab="launcher" title="Быстрый запуск" class="${tab==='launcher'?'active':''}">${icon('rocket')} Пуск</button><button data-island-tab="screenshots" title="Скриншоты" class="${tab==='screenshots'?'active':''}">${icon('camera')} Снимки</button><button class="island-settings" data-show-settings aria-label="Открыть настройки">${icon('sliders')}</button></div><div class="island-panel"><div class="island-panel-content">${tab==='launcher'?launcherPanel():tab==='screenshots'?screenshotPanel():tab==='capture'?capturePanel():tab==='music'&&s.showMusic?musicControls():tab==='weather'&&s.showWeather?islandWeather():todayPanelMarkup(hasWeather,w,s)}</div></div><div class="island-bottom"><span class="island-wordmark">${icon('spark')} EclipseIsland</span><span data-island-status role="status">${tab==='music'?'Ваш личный саундтрек':tab==='weather'?'Немного ближе к небу':'Побудьте в моменте'}</span><button data-collapse aria-label="Свернуть остров">${icon('minus')}</button></div></div></article>`;}
function islandWeather(){const w=state.weather;if(w.status!=='ready')return `<div class="island-empty">${icon('cloud')}<strong>${w.status==='loading'?'Смотрим, что за окном…':w.status==='error'?'Погода пока недоступна':'Какая погода у вас?'}</strong><span>${w.status==='error'?'Проверьте соединение с интернетом':'Выберите город в настройках'}</span><button class="text-button" data-show-weather-settings>Настроить ${icon('arrow')}</button></div>`;return `<div class="island-weather"><div><span>${icon('pin')} ${esc(w.city)}</span><strong>${Math.round(w.temperature)}°</strong><small>${weatherLabel(w.code,w.isDay)} · Ощущается как ${Math.round(w.feels)}°</small></div><div class="weather-orb">${icon(weatherIcon(w.code,w.isDay))}</div></div>`;}
function renderIsland(){
 const mount=document.querySelector('.island-mount');if(!mount)return;if(tab==='music'&&!state.settings.showMusic||tab==='weather'&&!state.settings.showWeather)tab='today';
 let island=mount.querySelector('.island');
 if(!island){mount.innerHTML=islandMarkup();island=mount.querySelector('.island');}
 else{
  const template=document.createElement('template');template.innerHTML=islandMarkup();const next=template.content.firstElementChild;
  island.dataset.renderer=state.settings.islandRenderer;setClass(island,'expanded',expanded);setClass(island,'is-activity-panel',['capture','launcher','screenshots'].includes(tab));setClass(island,'is-playing',state.media.playing&&state.settings.showMusic);
  if(island.querySelector('.island-compact').innerHTML!==next.querySelector('.island-compact').innerHTML)island.querySelector('.island-compact').replaceWith(next.querySelector('.island-compact'));
  const key=JSON.stringify([tab,state.settings.showMusic,state.settings.showWeather,['weather','today'].includes(tab)?state.weather:null]);
  if(island.dataset.panelKey!==key){island.dataset.panelKey=key;island.querySelector('.island-expanded').replaceWith(next.querySelector('.island-expanded'));}
  island.querySelector('.island-expanded').inert=!expanded;const button=island.querySelector('[data-expand]');button.setAttribute('aria-expanded',String(expanded));button.setAttribute('aria-label',expanded?'Свернуть остров':'Раскрыть остров');
 }
 mount.style.opacity=isOverlay?'1':state.settings.enabled?'1':'.4';updateClocks();updateMediaDOM();updateActivities();updateTools();observeBounds();syncUITimers();
}
function setExpanded(value,byHover=false){if(expanded===value)return;expanded=value;const island=document.querySelector('.island');if(!island)return;island.classList.toggle('expanded',expanded);island.querySelector('.island-expanded').inert=!expanded;const button=island.querySelector('[data-expand]');button.setAttribute('aria-expanded',String(value));button.setAttribute('aria-label',value?'Свернуть остров':'Раскрыть остров');if(!byHover)sound(value?'open':'close');updateProgress();syncUITimers();updateIslandHeight();reportBoundsDuringTransition();}
function sourceLabel(source=''){if(/spotify/i.test(source))return 'Spotify';if(/chrome/i.test(source))return 'Google Chrome';if(/msedge/i.test(source))return 'Microsoft Edge';if(/firefox/i.test(source))return 'Firefox';if(/yandex/i.test(source))return 'Яндекс Музыка';if(/vlc/i.test(source))return 'VLC';if(/zunemusic|musicplayer/i.test(source))return 'Медиапроигрыватель';return source?source.split(/[\\/!]/).pop().replace(/\.exe$/i,'').slice(0,38):'Системный плеер';}
function updateClocks(){const now=new Date();document.querySelectorAll('[data-clock]').forEach(el=>setText(el,clockText(state.settings,now)));document.querySelectorAll('[data-date]').forEach(el=>setText(el,now.toLocaleDateString('ru-RU',{weekday:'long',day:'numeric',month:'long'})));document.querySelectorAll('[data-short-date]').forEach(el=>setText(el,now.toLocaleDateString('ru-RU',{day:'numeric',month:'short'}).replace('.','')));}

function updateArtwork(){
  const m=state.media,src=safeArtwork(m.artwork);
  document.querySelectorAll('[data-artwork]').forEach(el=>{
    let image=el.querySelector('.cover-image');
    if(!src){image?.remove();setClass(el,'has-artwork',false);setClass(el,'artwork-loading',m.artworkStatus==='loading'&&!!m.active);return;}
    if(image?.getAttribute('src')===src)return;
    image?.remove();image=document.createElement('img');image.className='cover-image';image.alt='Обложка трека';image.draggable=false;
    image.addEventListener('load',()=>{if(image.isConnected){el.classList.add('has-artwork');el.classList.remove('artwork-loading');}});
    image.addEventListener('error',()=>{image.remove();el.classList.remove('has-artwork','artwork-loading');});
    image.src=src;el.append(image);
  });
}
function livePosition(){const m=state.media;const elapsed=m.playing&&m.receivedAt?Math.max(0,(Date.now()-m.receivedAt)/1000):0;return Math.min(m.duration||0,Math.max(0,(m.position||0)+elapsed));}
function updateProgress(){
  if(!playerVisible())return;
  const m=state.media,position=livePosition();
  if(!seeking)document.querySelectorAll('[data-position]').forEach(el=>setText(el,trackTime(position)));
  document.querySelectorAll('[data-duration]').forEach(el=>setText(el,trackTime(m.duration)));
  document.querySelectorAll('[data-seek]').forEach(el=>{
    if(!seeking){const max=String(m.duration||1);if(el.max!==max)el.max=max;el.value=position;const progress=`${m.duration?position/m.duration*100:0}%`;if(el.style.getPropertyValue('--progress')!==progress)el.style.setProperty('--progress',progress);}
    const disabled=!m.canSeek||!m.duration;if(el.disabled!==disabled)el.disabled=disabled;
  });
}
function updateMediaDOM(){
  const m=state.media;
  const island=document.querySelector('.island');
  if(island&&!!island.querySelector('.compact-track')!==!!(state.settings.showMusic&&m.active)){renderIsland();return;}
  document.querySelectorAll('[data-track-title]').forEach(el=>setText(el,m.active?(m.title||'Без названия'):(el.closest('.music-widget')?'Включите музыку':'Пока тихо')));
  document.querySelectorAll('[data-track-artist]').forEach(el=>setText(el,m.active?(m.artist||'Неизвестный исполнитель'):(el.closest('.music-widget')?'Ваш саундтрек появится здесь':'Включите музыку в любимом плеере')));
  document.querySelectorAll('[data-player-label]').forEach(el=>setText(el,m.active?sourceLabel(m.source):'Ожидание плеера'));
  document.querySelectorAll('[data-equalizer]').forEach(el=>setClass(el,'animated',m.playing));
  document.querySelectorAll('.album-art').forEach(el=>setClass(el,'playing',m.playing));
  document.querySelectorAll('[data-media]').forEach(el=>{
    const action=el.dataset.media,disabled=action==='refresh'?false:!m[{toggle:'canToggle',next:'canNext',previous:'canPrevious'}[action]];
    if(el.disabled!==disabled)el.disabled=disabled;setClass(el,'media-pending',pendingActions.has(action));setAttribute(el,'aria-busy',pendingActions.has(action));
    if(action==='toggle'){const name=m.playing?'pause':'play';if(el.dataset.icon!==name){el.innerHTML=icon(name);el.dataset.icon=name;}setAttribute(el,'aria-label',m.playing?'Пауза':'Воспроизвести');}
  });
  const compact=document.querySelector('.compact-track');if(compact)setText(compact,m.title||'Без названия');
  updateArtwork();if(uiVisible())updateProgress();
}

async function sendMedia(action,seconds){
  const id=++mediaCommandSequence;pendingActions.set(action,id);updateMediaDOM();
  try{const result=await api.media(action,seconds);if(!result.ok){sound('error');toast(result.error||'Плеер не поддерживает это действие');}}
  catch{sound('error');toast('Не удалось связаться с плеером');}
  finally{if(pendingActions.get(action)===id)pendingActions.delete(action);updateMediaDOM();}
}

function updateWeatherDOM(){const w=state.weather;document.querySelectorAll('[data-city-label]').forEach(el=>el.textContent=state.settings.city?.name||'Выберите город');document.querySelectorAll('[data-weather-widget]').forEach(el=>el.innerHTML=w.status==='ready'?`<div class="weather-summary"><strong>${Math.round(w.temperature)}<sup>°</sup></strong><span class="weather-symbol">${icon(weatherIcon(w.code,w.isDay))}</span></div><span class="muted">${weatherLabel(w.code,w.isDay)} · Ощущается как ${Math.round(w.feels)}°</span>`:`<div class="weather-summary"><strong class="empty-degree">—<sup>°</sup></strong><span class="weather-symbol muted">${icon('cloud')}</span></div><span class="muted">${w.status==='loading'?'Загружаем погоду…':w.status==='error'?'Нет соединения':'Как там за окном?'}</span>`);document.querySelectorAll('[data-weather-detail]').forEach(el=>el.innerHTML=w.status==='ready'?`<div class="weather-detail-top"><span>${icon('pin')} ${esc(w.city)}</span><button class="icon-button" data-refresh-weather aria-label="Обновить погоду">${icon('refresh')}</button></div><div class="weather-detail-main"><div><div class="weather-temperature">${Math.round(w.temperature)}°</div><h2>${weatherLabel(w.code,w.isDay)}</h2><p>Ощущается как ${Math.round(w.feels)}°</p></div><div class="weather-orb">${icon(weatherIcon(w.code,w.isDay))}</div></div><div class="weather-metrics"><span>Макс. <b>${Math.round(w.high)}°</b> · Мин. <b>${Math.round(w.low)}°</b></span><span>${icon('wind')} ${w.wind} м/с</span><span>Обновлено ${new Date(w.updatedAt).toLocaleTimeString('ru-RU',{hour:'2-digit',minute:'2-digit'})}</span></div>`:`<div class="weather-empty"><div class="weather-orb">${icon('cloud')}</div><h2>${w.status==='loading'?'Узнаём погоду…':w.status==='error'?'Облачно на линии связи':'Каждый день — своя погода.'}</h2><p>${w.status==='error'?esc(w.error||'Проверьте интернет и попробуйте снова'):'Выберите город, а обо всём остальном позаботимся мы.'}</p>${w.status==='error'?'<button class="button" data-refresh-weather>Попробовать ещё раз</button>':''}</div>`);}
function updateLive(){updateTools();updateClocks();updateMediaDOM();updateWeatherDOM();updateActivities();}
let resizeObserver,contentObserver,transitionFrame,transitionUntil=0;
// Measure the intrinsic content, not the animated/scroll-clipped panel itself.
// The existing shell height transition keeps the header fixed and moves the footer.
function updateIslandHeight(){
  const island=document.querySelector('.island.expanded');if(!island)return;
  const panel=island.querySelector('.island-panel'),content=panel?.querySelector('.island-panel-content');if(!content)return;
  const outer=el=>{const css=getComputedStyle(el);return el.offsetHeight+(parseFloat(css.marginTop)||0)+(parseFloat(css.marginBottom)||0);};
  const vertical=(el,...props)=>{const css=getComputedStyle(el);return props.reduce((sum,key)=>sum+(parseFloat(css[key])||0),0);};
  const height=Math.ceil(vertical(island,'borderTopWidth','borderBottomWidth','paddingTop','paddingBottom')+
    outer(island.querySelector('.island-compact'))+outer(island.querySelector('.transfer-band'))+
    vertical(island.querySelector('.island-expanded'),'paddingTop','paddingBottom')+
    outer(island.querySelector('.island-tabs'))+outer(island.querySelector('.island-bottom'))+
    vertical(panel,'paddingTop','paddingBottom','marginTop','marginBottom','borderTopWidth','borderBottomWidth')+outer(content));
  const target=height+'px';if(island.style.getPropertyValue('--expanded-height')!==target){island.style.setProperty('--expanded-height',target);reportBoundsDuringTransition();}
}
function reportBounds(){
  if(!isOverlay)return;const island=document.querySelector('.island');const r=island?.getBoundingClientRect();if(!r||r.width<=0||r.height<=0)return;
  const value={x:Math.round(r.x),y:Math.round(r.y),width:Math.round(r.width),height:Math.round(r.height),radius:Math.round(parseFloat(getComputedStyle(island).borderTopLeftRadius)*(state.settings.scale/100))};
  const key=JSON.stringify(value);if(lastBounds!==key){lastBounds=key;api.bounds(value);}
}
function reportBoundsDuringTransition(){
 if(!isOverlay||!uiVisible())return;if(transitionFrame)return;transitionUntil=performance.now()+440;
 let measuredAt=-Infinity;const frame=()=>{const now=performance.now();if(now-measuredAt>=32){reportBounds();measuredAt=now;}if(now<transitionUntil)transitionFrame=requestAnimationFrame(frame);else{transitionFrame=0;reportBounds();}};
 transitionFrame=requestAnimationFrame(frame);
}

function observeBounds(){
  resizeObserver?.disconnect();contentObserver?.disconnect();
  const island=document.querySelector('.island');if(!island)return;
  updateIslandHeight();
  if(typeof ResizeObserver!=='undefined'){
    contentObserver=new ResizeObserver(updateIslandHeight);
    island.querySelectorAll('.island-panel-content,.island-tabs,.island-bottom,.island-compact,.transfer-band').forEach(el=>contentObserver.observe(el));
    if(isOverlay){resizeObserver=new ResizeObserver(()=>{if(!transitionFrame)reportBounds();});resizeObserver.observe(island);}
  }
  reportBoundsDuringTransition();
}

app.addEventListener('click',async event=>{
  const el=event.target.closest('button');if(!el)return;
  if(el.hasAttribute('data-process-open')){openProcessPicker();return;}
  if(el.hasAttribute('data-process-refresh')){openProcessPicker();return;}
  if(el.hasAttribute('data-process-close')){processPickerOpen=false;renderProcesses();return;}
  if(el.hasAttribute('data-launcher-action')){try{const action=el.dataset.launcherAction,result=await api.launcher(action,el.dataset.entryId,action==='move'?Number(el.dataset.direction):el.dataset.entryKind);if(result?.ok===false)toast(result.error);else if(action==='open'&&isOverlay)setExpanded(false);else if(action==='open-all')toast('Запущено '+result.launched+' из '+result.total);}catch(error){toast(error.message);}return;}
  if(el.hasAttribute('data-shot-action')){try{const action=el.dataset.shotAction,result=await api.screenshot(action,el.dataset.shotId);if(result?.ok===false||result?.error)toast(result.error);else if(!result?.canceled&&['area','screen','copy'].includes(action))toast(action==='copy'?'Картинка скопирована':result.copied?'Скриншот сохранён и скопирован':'Скриншот сохранён');}catch(error){toast(error.message);}return;}
  if(el.hasAttribute('data-shot-folder-change')){try{await api.screenshotFolder();}catch(error){toast(error.message);}return;}
  if(el.hasAttribute('data-completion-preview')){playCompletion(state.settings[el.dataset.completionPreview+'Tone'],state.settings.completionVolume);return;}
  if(el.hasAttribute('data-download-action')){try{const result=await api.downloads(el.dataset.downloadAction,el.dataset.downloadId);if(result?.ok===false)toast(result.error||'Загрузка недоступна');}catch(error){toast(error.message||'Не удалось открыть загрузку');}return;}
  if(el.hasAttribute('data-tools-settings')){if(isOverlay)api.showSettings(el.dataset.toolsSettings);else navigate(el.dataset.toolsSettings);return;}
  if(el.hasAttribute('data-open-capture')){tab='capture';expanded=true;renderIsland();}
  else if(el.hasAttribute('data-transfer-action')){try{const result=await api.transfer(el.dataset.transferAction,el.dataset.transferId);if(!result?.ok)toast(result?.error||'Операция недоступна');}catch{toast('Операция уже завершилась');}}
  else if(el.hasAttribute('data-capture-settings')){if(isOverlay)api.showSettings('capture');else navigate('capture');}
  else if(el.hasAttribute('data-capture-profile')){const profile={eco:{height:720,fps:30},balanced:{height:1080,fps:60},quality:{height:1440,fps:60}}[el.dataset.captureProfile];if(profile)await saveCapture({...profile,quality:'auto',codec:'auto'});}
  else if(el.hasAttribute('data-capture-action')){try{const result=await api.capture(el.dataset.captureAction,el.dataset.recordingId);if(result?.ok===false||result?.error)toast(result.error||'Действие недоступно');}catch(error){toast(error.message||'Не удалось выполнить действие записи');}}
  else if(el.hasAttribute('data-capture-folder')){try{state.capture=await api.captureFolder();updateCaptureDOM();}catch(error){toast(error.message||'Не удалось выбрать папку');}}
  else if(el.hasAttribute('data-capture-refresh'))loadCaptureSources();
  else if(el.hasAttribute('data-capture-source')){await saveCapture({source:el.dataset.captureSource});const grid=document.querySelector('[data-capture-sources]');if(grid)grid.innerHTML=captureSourcesMarkup();}
  else if(el.dataset.nav){sound('navigate');navigate(el.dataset.nav);}
  else if(el.hasAttribute('data-expand')){clearTimeout(hoverTimer);clearTimeout(leaveTimer);setExpanded(!expanded);}
  else if(el.hasAttribute('data-collapse'))setExpanded(false);
  else if(el.dataset.islandTab){tab=el.dataset.islandTab;sound('navigate');renderIsland();}
  else if(el.dataset.accent){sound('success');save({accent:el.dataset.accent});}
  else if(el.dataset.colorTheme){const preset=colorThemes.find(([id])=>id===el.dataset.colorTheme);if(preset){sound('success');save(preset[2]);}}
  else if(el.hasAttribute('data-reset-theme')){sound('success');save(Object.fromEntries(themeKeys.map(key=>[key,DEFAULTS[key]])));}
  else if(el.dataset.rendererPreset){const mode=el.dataset.rendererPreset;sound('success');save({uiRenderer:mode,islandRenderer:mode,loaderRenderer:mode});}
  else if(el.dataset.media){sound(['next','previous'].includes(el.dataset.media)?el.dataset.media:'tap');sendMedia(el.dataset.media);}
  else if(el.hasAttribute('data-show-settings')){sound('navigate');if(isOverlay)api.showSettings();else navigate('appearance');}
  else if(el.hasAttribute('data-show-weather-settings')){sound('navigate');if(isOverlay)api.showSettings();else navigate('weather');}
  else if(el.hasAttribute('data-refresh-weather')){sound();el.disabled=true;await api.refreshWeather();if(document.contains(el))el.disabled=false;}
  else if(el.dataset.city!==undefined){sound('success');const city=cityResults[Number(el.dataset.city)];if(city){try{const results=document.querySelector('#city-results');if(results)results.innerHTML='';const search=document.querySelector('#city-search');if(search)search.value='';await api.selectCity(city);renderPage();}catch{toast('Не удалось сохранить город');}}}
  else if(el.hasAttribute('data-minimize')){sound('close');if(state.platform==='browser')toast('Свернуть окно можно в приложении Windows');else api.minimize();}
  else if(el.hasAttribute('data-close')){sound('close');if(state.platform==='browser')toast('В Windows настройки скрываются, а остров остаётся на экране');else api.close();}
  else if(el.hasAttribute('data-quit')){if(state.platform==='browser')toast('Это предпросмотр интерфейса. Закройте вкладку, чтобы выйти.');else api.quit();}
});
app.addEventListener('change',event=>{
  if(event.target.matches('[data-tools-setting]')){const el=event.target,key=el.dataset.toolsSetting,value=el.type==='checkbox'?el.checked:key==='format'||key==='monitor'&&['cursor','primary'].includes(el.value)?el.value:Number(el.value);api.toolsSettings({[key]:value}).then(result=>{if(result?.ok===false)toast(result.error);}).catch(error=>{toast(error.message);updateTools();});return;}
  if(event.target.matches('[data-launcher-name]')){api.launcher('rename',event.target.dataset.launcherName,event.target.value).then(r=>{if(r?.ok===false)toast(r.error);}).catch(error=>toast(error.message));return;}
  if(event.target.matches('[data-tools-copy]')){api.toolsSettings({copy:event.target.checked}).catch(error=>toast(error.message));return;}
  if(event.target.matches('[data-capture-setting]')){const el=event.target,key=el.dataset.captureSetting;saveCapture({...(['bitrate','replayBitrate'].includes(key)?{[key==='bitrate'?'quality':'replayQuality']:'manual'}:{}),[key]:el.type==='checkbox'?el.checked:['quality','replayQuality','source','codec','hotkey','panelHotkey','replayHotkey'].includes(key)?el.value:Number(el.value)});return;}

  const el=event.target;
  if(el.matches('[data-all-renderer]')){sound('success');save({uiRenderer:el.value,islandRenderer:el.value,loaderRenderer:el.value});return;}
  if(el.matches('[data-setting]')){const key=el.dataset.setting;const value=el.type==='checkbox'?el.checked:el.type==='range'?Number(el.value):key==='autoLaunch'?el.value==='true':key==='monitor'&&el.value!=='primary'?Number(el.value):el.value;sound(el.type==='checkbox'?(el.checked?'on':'off'):key==='autoLaunch'?(el.value==='true'?'on':'off'):'tap');save({[key]:value,...(key==='customAccent'?{accent:'custom'}:{})});}
  if(el.matches('[data-seek]')){seeking=false;sendMedia('seek',Number(el.value));}
});
app.addEventListener('pointerdown',event=>{
  if(event.target.matches('[data-seek]'))seeking=true;
  const button=event.target.closest('button');if(!button||button.disabled||state.settings.reducedMotion)return;
  button.classList.add('button-press');setTimeout(()=>button.classList.remove('button-press'),460);
  if(!button.matches('.nav-item,.icon-button,.play-button,.button,.renderer-card,.island-tabs>button'))return;
  const wave=document.createElement('span');wave.className='press-wave';const r=button.getBoundingClientRect();
  wave.style.left=`${event.clientX-r.left}px`;wave.style.top=`${event.clientY-r.top}px`;button.append(wave);
  setTimeout(()=>{button.classList.remove('button-press');wave.remove();},460);
});
app.addEventListener('pointercancel',()=>{seeking=false;});
app.addEventListener('pointerup',()=>{setTimeout(()=>{seeking=false;},0);});

app.addEventListener('input',event=>{if(event.target.matches('[data-launcher-search]')){launcherQuery=event.target.value;updateTools();}if(event.target.matches('[data-process-search]')){processQuery=event.target.value;renderProcesses();}if(event.target.matches('[data-tools-setting="quality"]'))document.querySelectorAll('[data-tools-quality]').forEach(el=>setText(el,event.target.value+'%'));});
app.addEventListener('pointerdown',event=>{if(isOverlay&&event.target.matches('[data-launcher-search]'))api.focusInput?.(true);});
app.addEventListener('focusin',event=>{if(isOverlay&&event.target.matches('[data-launcher-search]'))api.focusInput?.(true);});
app.addEventListener('focusout',event=>{if(isOverlay&&event.target.matches('[data-launcher-search]'))api.focusInput?.(false);});
app.addEventListener('input',event=>{
  const el=event.target;
  if(el.matches('[data-seek]')){seeking=true;document.querySelectorAll('[data-position]').forEach(item=>item.textContent=trackTime(el.value));el.style.setProperty('--progress',`${Number(el.value)/Number(el.max)*100}%`);}
  if(el.matches('input[type=range][data-setting],input[type=color][data-setting]')){
    const key=el.dataset.setting,value=el.type==='range'?Number(el.value):el.value;
    const temporary={...state.settings,...themePatch({[key]:value,...(key==='customAccent'?{accent:'custom'}:{})})};
    applyTheme(temporary);
    const output=document.querySelector(`[data-setting-value="${key}"]`);if(output)output.textContent=el.value+settingSuffix(key);
    const colorOutput=document.querySelector(`[data-color-value="${key}"]`);if(colorOutput)colorOutput.textContent=el.value;
    if(key==='scale')document.documentElement.style.setProperty('--island-scale',value/100);
    reportBoundsDuringTransition();
  }
  if(el.id==='city-search'){clearTimeout(searchTimer);const query=el.value.trim();const results=document.querySelector('#city-results');const generation=++searchGeneration;if(query.length<2){results.innerHTML='';return;}results.innerHTML='<div class="search-message">Ищем ваш город…</div>';searchTimer=setTimeout(async()=>{const result=await api.cities(query);if(generation!==searchGeneration||!document.contains(results))return;cityResults=result.items||[];results.innerHTML=result.ok?(cityResults.length?cityResults.map((c,i)=>`<button class="city-result" data-city="${i}">${icon('pin')}<span><strong>${esc(c.name)}</strong><small>${esc(c.country)}</small></span>${icon('arrow')}</button>`).join(''):'<div class="search-message">Город не найден. Попробуйте другое название.</div>'):`<div class="search-message">${esc(result.error)}</div>`;},400);}});
app.addEventListener('pointerover',event=>{if(event.target.closest('[data-activity-band],[data-transfer-band]')){clearTimeout(hoverTimer);return;}if(!event.target.closest('.island')||!state.settings.hoverExpand)return;clearTimeout(leaveTimer);if(!expanded){clearTimeout(hoverTimer);hoverTimer=setTimeout(()=>setExpanded(true,true),480);}});
app.addEventListener('pointerout',event=>{if(!event.target.closest('.island')||event.relatedTarget?.closest?.('.island'))return;clearTimeout(hoverTimer);if(state.settings.hoverExpand){clearTimeout(leaveTimer);leaveTimer=setTimeout(()=>setExpanded(false,true),900);}});
document.addEventListener('keydown',event=>{if(event.key==='Escape'&&toolsState().busy)api.screenshot('cancel').catch(()=>{});if(event.key==='Escape'){clearTimeout(leaveTimer);setExpanded(false);}});
document.addEventListener('pointerdown',()=>{if(state.settings.sounds){try{audioContext??=new AudioContext();audioContext.resume();}catch{}}},{once:true});
function receiveSnapshot(value){
  if(value.tools){state.tools=value.tools;updateTools();}
  if(value.spotifySetup)state.spotifySetup=value.spotifySetup;
  if(value.capture)state.capture=value.capture;if(value.transfers)state.transfers=value.transfers;if(value.replay)state.replay=value.replay;if(value.downloads)state.downloads=value.downloads;
  if(value.settings)receiveSettings(value.settings);
  if(value.weather){state.weather=value.weather;updateWeatherDOM();}
  if(value.media){const active=!!state.media.active;state.media=mergeMedia({},value.media);if(active!==!!state.media.active)renderIsland();updateMediaDOM();}
  if(value.autostart){state.autostart=value.autostart;updateStartupStatus();}
  syncUITimers();
}
api.on(message=>{
  if(message.type==='completion-sound'){playCompletion(message.value.tone,message.value.volume);return;}
  if(message.type==='downloads'){state.downloads=message.value;updateActivities();return;}
  if(message.type==='tools'){const previous=state.tools?.recent?.[0]?.id;state.tools=message.value;const latest=state.tools.recent?.[0];if(!state.tools.busy&&state.tools.settings?.notifications!==false&&latest&&latest.id!==previous){captureNotice={kind:'screenshot',text:'Скриншот сохранён · открыть',id:latest.id,until:Date.now()+4500};clearTimeout(captureNoticeTimer);captureNoticeTimer=setTimeout(()=>{captureNotice=null;updateActivities();},4500);updateActivities();}updateTools();return;}
  if(message.type==='tools-panel'){openToolPanel(message.value);return;}
  if(message.type==='view-visible'){nativeVisible=!!message.value;if(nativeVisible){lastBounds='';requestAnimationFrame(()=>reportBoundsDuringTransition());updateClocks();updateMediaDOM();}syncUITimers();return;}
  if(message.type==='snapshot'){receiveSnapshot(message.value);if(uiVisible()&&message.sequence)api.mediaApplied?.(message.sequence);return;}
  if(message.type==='spotify-setup'){state.spotifySetup=message.value;return;}
  if(message.type==='capture'){
    const previous=state.capture,old=previous?.status;state.capture=message.value;
    if(state.capture.error&&state.capture.error!==previous?.error||state.capture.lastSaved&&state.capture.lastSaved!==previous?.lastSaved){
      captureNotice={error:!!state.capture.error,text:state.capture.error?'Запись: '+state.capture.error:'Видео сохранено. Нажмите для просмотра',id:state.capture.lastSaved,until:Date.now()+8000};clearTimeout(captureNoticeTimer);captureNoticeTimer=setTimeout(()=>{captureNotice=null;updateActivities();},8000);
    }
    if(tab==='capture'&&old!==state.capture.status)renderIsland();updateActivities();return;
  }
  if(message.type==='replay'){state.replay=message.value;updateActivities();return;}
  if(message.type==='transfers'){state.transfers=message.value;updateTransfers();return;}
  if(message.type==='overlay-visibility'){const value=message.value;document.documentElement.classList.toggle('overlay-concealed',!value.visible);if(value.visible){const panel=document.querySelector('.island-expanded');if(panel)panel.inert=!expanded;lastBounds='';document.documentElement.classList.toggle('overlay-showing',!!value.animate);clearTimeout(overlayShowTimer);overlayShowTimer=setTimeout(()=>{document.documentElement.classList.remove('overlay-showing');lastBounds='';reportBounds();},260);requestActivityHeartbeat();requestAnimationFrame(()=>reportBoundsDuringTransition());}return;}
  if(message.type==='capture-panel'){if(isOverlay){tab='capture';expanded=true;renderIsland();}else navigate('capture');return;}
  if(message.type==='shortcuts'){state.shortcuts=message.value;updateCaptureDOM();if(!isOverlay&&page==='shortcuts')renderPage();return;}
  if(message.type==='autostart'){state.autostart=message.value;updateStartupStatus();return;}
  if(message.type==='expand'){setExpanded(!expanded);return;}
  if(message.type==='media'){
    const active=!!state.media.active,playing=!!state.media.playing;if(message.value.trackKey&&message.value.trackKey!==state.media.trackKey)seeking=false;state.media=mergeMedia(state.media,message.value);if(message.value.sessions)updateSourceOptions();
    if(!uiVisible())return;
    if(Object.keys(message.value).every(key=>['trackKey','position','duration'].includes(key))){updateProgress();return;}
    if(active!==!!state.media.active)renderIsland();updateMediaDOM();if(message.sequence)api.mediaApplied?.(message.sequence);if(playing!==!!state.media.playing)syncUITimers();return;
  }
  if(message.type==='settings'){
    if(JSON.stringify({...DEFAULTS,...message.value})!==JSON.stringify(state.settings))receiveSettings(message.value);
  }else if(message.type==='weather'){state.weather=message.value;updateWeatherDOM();renderIsland();}
});
setInterval(requestActivityHeartbeat,750);
document.addEventListener('visibilitychange',()=>{if(uiVisible()){updateClocks();updateMediaDOM();}syncUITimers();});
window.addEventListener('beforeunload',()=>{clearTimeout(clockTimer);clearTimeout(progressTimer);clearTimeout(hoverTimer);clearTimeout(leaveTimer);cancelAnimationFrame(transitionFrame);resizeObserver?.disconnect();});

async function boot(){try{state={...state,...await api.init()};state.settings=syncIslandAccent({...DEFAULTS,...state.settings});state.media=mergeMedia({},state.media);applyTheme(state.settings);renderShell();renderPage();if(isOverlay){renderIsland();applySettings();}if(pendingToolPanel){const pending=pendingToolPanel;pendingToolPanel=null;openToolPanel(pending);}if(state.platform==='browser'&&!isOverlay){document.body.classList.add('browser-preview');const badge=document.createElement('div');badge.className='browser-notice';badge.textContent='Предпросмотр интерфейса · Оверлей и системная музыка работают в приложении Windows';document.querySelector('.workspace').append(badge);if(state.settings.city)api.refreshWeather();}document.querySelector('#boot-loader')?.remove();if(isOverlay&&state.platform!=='browser')sound('startup');syncUITimers();}catch(error){app.innerHTML='<div class="boot-error"><h1>Не удалось открыть EclipseIsland</h1><p>Перезапустите приложение.</p></div>';document.querySelector('#boot-loader')?.remove();console.error(error);}}
initControls({sound,preview:(key,value)=>applyTheme({...state.settings,...themePatch({[key]:value,...(key==='customAccent'?{accent:'custom'}:{})})}),cancelPreview:()=>applyTheme(state.settings)});
boot();
